window.QB_TKP_B13 = [
{id:"TKP-2001", q:"Anda dan Dedi satu tim menyusun proposal program kerja dinas. Dua hari sebelum deadline, Dedi belum menyelesaikan bagiannya karena anaknya dirawat di rumah sakit. Sikap yang paling tepat adalah ....", opts:[{t:"Membantu mengerjakan bagian Dedi agar deadline terpenuhi, lalu menyampaikan kondisi sebenarnya kepada atasan dengan tetap menjaga nama baik Dedi", s:5},{t:"Mengerjakan bagian Dedi tanpa banyak bertanya agar proposal selesai tepat waktu", s:4},{t:"Melaporkan kepada atasan bahwa Dedi belum menyelesaikan tugasnya dan menunggu arahan", s:3},{t:"Membiarkan bagian Dedi kosong karena itu bukan tanggung jawab Anda", s:2},{t:"Menceritakan kepada rekan lain bahwa Dedi tidak profesional mencampur urusan keluarga dengan pekerjaan", s:1}], ex:"Menolong rekan yang kesulitan demi kepentingan tim sekaligus jujur kepada atasan mencerminkan kerjasama dan empati; menjelekkan rekan justru merusak kekompakan tim."},
{id:"TKP-2002", q:"Dua rekan Anda, Agus dan Budi, berselisih paham soal pembagian tugas piket pelayanan hingga suasana kantor kecamatan menjadi tidak nyaman. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak keduanya berdiskusi secara musyawarah untuk menyusun ulang pembagian tugas yang adil dan disepakati bersama", s:5},{t:"Menengahi dengan membagi tugas piket secara bergantian agar keduanya mendapat bagian yang sama", s:4},{t:"Tidak ikut campur karena itu urusan pribadi mereka berdua", s:3},{t:"Memihak salah satu yang menurut Anda paling benar agar perselisihan cepat selesai", s:2},{t:"Menyebarkan cerita perselisihan mereka ke rekan lain agar keduanya malu dan berhenti bertengkar", s:1}], ex:"Menyelesaikan konflik melalui musyawarah dengan solusi yang adil mencerminkan semangat kerjasama tim; memihak atau mengadu domba hanya memperkeruh keadaan."},
{id:"TKP-2003", q:"Dalam tim penyusun laporan tahunan, Siti selalu menunggak menyerahkan datanya sehingga kerja tim lain ikut terhambat. Sikap yang paling tepat adalah ....", opts:[{t:"Berbicara baik-baik dengan Siti untuk mengetahui kendalanya, menawarkan bantuan, dan menyepakati tenggat yang realistis bersama tim", s:5},{t:"Mengingatkan Siti secara tegas agar segera menyerahkan datanya demi kelancaran tim", s:4},{t:"Mengerjakan sendiri bagian Siti agar laporan tidak terlambat tanpa menegurnya", s:3},{t:"Membiarkan saja karena menegur rekan bisa merusak hubungan pertemanan", s:2},{t:"Melaporkan Siti ke atasan sebagai pegawai malas agar ia mendapat sanksi", s:1}], ex:"Pendekatan empatik disertai solusi konkret menjaga kekompakan tim; langsung menuntut sanksi tanpa dialog bertentangan dengan semangat pembinaan dalam kerjasama."},
{id:"TKP-2004", q:"Rapat koordinasi rutin kantor Anda selalu dijadwalkan Jumat pukul 11.30, sehingga rekan-rekan yang beragama Islam sering tergesa-gesa menunaikan shalat Jumat. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan dalam rapat agar jadwal dimajukan atau dimundurkan sehingga tidak mengganggu waktu ibadah, demi kenyamanan seluruh peserta", s:5},{t:"Meminta izin kepada pimpinan rapat agar rekan yang akan shalat Jumat boleh keluar lebih dulu", s:4},{t:"Diam saja karena jadwal sudah menjadi kebiasaan dan bukan wewenang Anda mengubahnya", s:3},{t:"Menyarankan rekan-rekan menunda shalat Jumat karena rapat dinas lebih penting", s:2},{t:"Memprotes keras panitia rapat di depan semua peserta karena dianggap tidak menghargai umat Islam", s:1}], ex:"Mengusulkan penyesuaian jadwal secara santun menunjukkan toleransi beragama dan kepedulian pada rekan; memprotes dengan emosi justru merusak suasana kerjasama."},
{id:"TKP-2005", q:"Anda menemukan ide dan data yang Anda susun dipresentasikan Joko dalam rapat seolah-olah itu hasil kerjanya sendiri. Sikap yang paling tepat adalah ....", opts:[{t:"Berbicara langsung dengan Joko secara pribadi, menyampaikan keberatan dengan tenang, dan menyepakati pengakuan kontribusi yang jujur ke depannya", s:5},{t:"Menegur Joko agar tidak mengulangi perbuatannya dan meminta ia mengklarifikasi ke atasan", s:4},{t:"Mendiamkan saja karena mempermasalahkannya hanya akan menimbulkan konflik terbuka", s:3},{t:"Membalas dengan mengklaim hasil kerja Joko sebagai milik Anda dalam kesempatan berikutnya", s:2},{t:"Mempermalukan Joko di depan seluruh peserta rapat agar ia jera", s:1}], ex:"Menyelesaikan secara pribadi dengan tenang menjunjung kejujuran sekaligus menjaga hubungan kerja; mempermalukan rekan di depan umum merusak martabat dan kekompakan tim."},
{id:"TKP-2006", q:"Seorang CPNS baru di unit Anda, Fajar, tampak kesulitan mengoperasikan aplikasi administrasi yang menjadi alat kerja utama tim. Sikap yang paling tepat adalah ....", opts:[{t:"Meluiangkan waktu membimbing Fajar sampai ia mandiri, bahkan membuatkan panduan singkat agar ia tidak tertinggal dari ritme tim", s:5},{t:"Menjelaskan cara penggunaan aplikasi kepada Fajar saat ia bertanya", s:4},{t:"Menyarankan Fajar belajar sendiri dari buku manual karena semua pegawai dulu juga begitu", s:3},{t:"Mengabaikannya karena membimbing bukan tugas Anda dan akan mengganggu pekerjaan sendiri", s:2},{t:"Mengeluhkan Fajar ke atasan sebagai pegawai yang tidak kompeten", s:1}], ex:"Membimbing rekan baru secara proaktif mempercepat kemandiriannya dan memperkuat tim; membiarkannya tertinggal merugikan kinerja tim secara keseluruhan."},
{id:"TKP-2007", q:"Kantor Anda mengadakan buka puasa bersama dan Maya yang beragama Kristen ditunjuk sebagai ketua panitia. Beberapa rekan mempertanyakan penunjukan itu. Sikap yang paling tepat adalah ....", opts:[{t:"Mendukung Maya sepenuhnya dan menjelaskan bahwa kepanitiaan adalah soal kemampuan berorganisasi, bukan soal agama, sambil memastikan kebutuhan ibadah puasa tetap terpenuhi", s:5},{t:"Tetap membantu kepanitiaan Maya agar acara berjalan lancar meski ada yang mempertanyakan", s:4},{t:"Tidak ikut campur dalam perdebatan penunjukan ketua panitia", s:3},{t:"Ikut mempertanyakan penunjukan Maya karena acara keagamaan sebaiknya dipimpin yang seagama", s:2},{t:"Menolak menghadiri acara tersebut sebagai bentuk protes atas penunjukan Maya", s:1}], ex:"Menilai rekan dari kemampuan bukan agamanya adalah wujud toleransi dan persatuan; mempersoalkan agama ketua panitia justru menumbuhkan diskriminasi di lingkungan kerja."},
{id:"TKP-2008", q:"Dalam rapat tim, Anda dan Hendra berbeda pendapat tajam mengenai metode pendataan warga yang akan dipakai. Perdebatan mulai memanas. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan agar kedua metode diuji pada sampel kecil terlebih dahulu, lalu tim bermusyawarah memilih berdasarkan hasil yang terbukti lebih baik", s:5},{t:"Mengalah dan mengikuti metode Hendra agar rapat cepat selesai dan suasana kembali kondusif", s:4},{t:"Bersikeras mempertahankan pendapat karena Anda yakin metode Anda lebih benar", s:3},{t:"Keluar dari ruangan rapat karena tidak tahan dengan perdebatan yang memanas", s:2},{t:"Menyerang pribadi Hendra di depan peserta rapat agar pendapatnya tidak didengar", s:1}], ex:"Menguji kedua pendapat secara objektif lalu bermusyawarah mencerminkan kedewasaan berorganisasi; menyerang pribadi lawan diskusi merusak etika musyawarah."},
{id:"TKP-2009", q:"Ratna, rekan satu tim piket pelayanan kelurahan, jatuh sakit mendadak padahal antrean warga sedang ramai. Sikap yang paling tepat adalah ....", opts:[{t:"Segera mengambil alih tugas Ratna sambil mengatur ulang pembagian kerja dengan rekan lain agar pelayanan warga tidak terganggu", s:5},{t:"Menggantikan Ratna melayani warga sampai jam piketnya selesai", s:4},{t:"Melaporkan kondisi Ratna ke atasan dan menunggu penugasan pengganti resmi", s:3},{t:"Tetap mengerjakan tugas sendiri saja karena menggantikan orang lain bukan kewajiban Anda", s:2},{t:"Mengeluh kepada warga bahwa pelayanan lambat karena Ratna sakit", s:1}], ex:"Sigap mengambil alih tugas rekan yang sakit demi kelangsungan pelayanan menunjukkan solidaritas tim; mengeluh kepada warga justru mencoreng citra instansi."},
{id:"TKP-2010", q:"Di grup WhatsApp kantor, seorang rekan mengirim lelucon yang merendahkan salah satu suku. Beberapa rekan tertawa menanggapinya. Sikap yang paling tepat adalah ....", opts:[{t:"Menegur dengan santun di grup bahwa candaan berbasis suku tidak pantas, serta mengingatkan pentingnya saling menghormati keberagaman", s:5},{t:"Mengirim pesan pribadi kepada pengirim lelucon agar tidak mengulangi perbuatannya", s:4},{t:"Diam saja karena hanya lelucon dan tidak ada yang benar-benar tersinggung", s:3},{t:"Ikut tertawa agar tidak dianggap kaku oleh rekan-rekan", s:2},{t:"Meneruskan lelucon tersebut ke grup lain karena dianggap lucu", s:1}], ex:"Menegur candaan SARA secara santun melindungi martabat rekan dan menjaga persatuan; ikut menyebarkannya berarti ikut merendahkan sesama anak bangsa."},
{id:"TKP-2011", q:"Kesalahan input data yang dilakukan Dewi menyebabkan laporan bersama tim Anda ditolak atasan dan harus dikerjakan ulang. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak Dewi memeriksa bersama letak kesalahannya, memperbaikinya berdua, lalu membuat daftar periksa agar kesalahan serupa tidak terulang", s:5},{t:"Membantu Dewi memperbaiki laporan tersebut agar bisa segera diserahkan kembali", s:4},{t:"Menyerahkan sepenuhnya kepada Dewi untuk memperbaiki karena ia yang bersalah", s:3},{t:"Menyalahkan Dewi di depan tim agar ia lebih berhati-hati di kemudian hari", s:2},{t:"Melaporkan Dewi ke atasan sebagai pegawai ceroboh yang menghambat kerja tim", s:1}], ex:"Memperbaiki kesalahan bersama sambil membangun sistem pencegahan mencerminkan tanggung jawab kolektif tim; menyalahkan rekan hanya menimbulkan luka tanpa solusi."},
{id:"TKP-2012", q:"Slamet yang bersuku Jawa mengundang seluruh tim ke upacara adat pernikahan adat Jawa di rumahnya. Sikap yang paling tepat adalah ....", opts:[{t:"Menghadiri undangan dengan penuh hormat, mengikuti tata cara adat yang berlaku, sebagai bentuk penghargaan pada budaya rekan", s:5},{t:"Menghadiri undangan tersebut sebagai bentuk dukungan kepada Slamet", s:4},{t:"Memberi ucapan selamat saja tanpa hadir karena merasa tidak paham adat Jawa", s:3},{t:"Menolak hadir dengan alasan kesibukan padahal sebenarnya tidak tertarik pada adat daerah lain", s:2},{t:"Mengejek adat pernikahan Jawa sebagai kuno di depan rekan-rekan", s:1}], ex:"Menghadiri dan menghormati upacara adat rekan mempererat persaudaraan lintas budaya; merendahkan adat suku lain bertentangan dengan semangat Bhinneka Tunggal Ika."},
{id:"TKP-2013", q:"Pembagian tugas piket malam di kantor Anda dinilai tidak adil karena pegawai junior selalu mendapat jadwal lebih banyak. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan dalam forum tim agar jadwal piket disusun ulang secara bergilir dan transparan sehingga beban terbagi adil bagi semua", s:5},{t:"Meminta atasan meninjau ulang jadwal piket agar lebih adil", s:4},{t:"Menerima saja jadwal yang ada karena sebagai junior memang sudah seharusnya lebih banyak piket", s:3},{t:"Menolak jadwal piket yang diberikan kepada Anda sebagai bentuk protes", s:2},{t:"Menghasut pegawai junior lain untuk bersama-sama mogok piket", s:1}], ex:"Mengusulkan sistem bergilir yang transparan menyelesaikan ketidakadilan secara musyawarah; menghasut mogok justru merusak disiplin dan kekompakan tim."},
{id:"TKP-2014", q:"Kantor menerapkan sistem administrasi digital baru, tetapi Wulan menolak mempelajarinya dan tetap memakai cara manual sehingga menghambat alur kerja tim. Sikap yang paling tepat adalah ....", opts:[{t:"Menawarkan diri mendampingi Wulan berlatih memakai sistem baru secara bertahap sampai ia nyaman, sambil menjelaskan manfaatnya bagi tim", s:5},{t:"Menjelaskan kepada Wulan bahwa sistem baru wajib dipakai semua pegawai", s:4},{t:"Membiarkan Wulan dengan cara manualnya karena itu pilihannya sendiri", s:3},{t:"Mengerjakan ulang secara digital semua pekerjaan manual Wulan tanpa memberitahunya", s:2},{t:"Mendesak atasan memberi sanksi kepada Wulan karena menghambat modernisasi", s:1}], ex:"Mendampingi rekan beradaptasi dengan perubahan menunjukkan empati dan kerjasama; langsung menuntut sanksi tanpa pembinaan mengabaikan semangat membesarkan tim bersama."},
{id:"TKP-2015", q:"Anda menjadi sekretaris panitia perayaan HUT kemerdekaan di kecamatan. Saat menyusun susunan acara, muncul usul agar doa pembuka hanya dipimpin satu agama tertentu. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan agar doa dipimpin bergantian perwakilan tiap agama atau dilakukan doa bersama secara universal yang menghormati semua keyakinan", s:5},{t:"Menetapkan doa pembuka dipimpin perwakilan agama yang ditunjuk secara bergilir setiap tahun", s:4},{t:"Mengikuti saja usul yang ada agar tidak memperpanjang perdebatan panitia", s:3},{t:"Mendukung usul doa satu agama karena mayoritas peserta memang beragama tersebut", s:2},{t:"Menolak mentah-mentah usul tersebut dengan nada marah di depan panitia", s:1}], ex:"Doa yang inklusif atau bergilir menghormati seluruh keyakinan peserta; memaksakan satu agama dalam acara bersama mengingkari semangat toleransi."},
{id:"TKP-2016", q:"Target kinerja tim Anda triwulan ini tidak tercapai, lalu dalam evaluasi para anggota saling menyalahkan. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak tim mengevaluasi secara objektif faktor penyebab kegagalan tanpa mencari kambing hitam, lalu menyusun rencana perbaikan bersama", s:5},{t:"Mengakui bagian kesalahan Anda dan mengajak rekan lain fokus pada perbaikan ke depan", s:4},{t:"Diam selama evaluasi karena takut ikut disalahkan", s:3},{t:"Ikut menyalahkan rekan yang menurut Anda paling bertanggung jawab atas kegagalan", s:2},{t:"Menyebarkan ke unit lain bahwa kegagalan tim disebabkan oleh rekan-rekan yang tidak becus", s:1}], ex:"Evaluasi objektif yang berorientasi solusi mencerminkan tanggung jawab kolektif; saling menyalahkan dan mengumbar kegagalan tim merusak kepercayaan antaranggota."},
{id:"TKP-2017", q:"Rekan Anda, Bambang, meminta Anda menandatangani daftar hadir rapat padahal ia tidak hadir, dengan alasan ia ada keperluan mendadak. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas namun santun, menjelaskan bahwa hal itu melanggar kejujuran, dan menyarankan Bambang mengajukan izin resmi", s:5},{t:"Menolak permintaan Bambang karena tidak ingin terlibat masalah", s:4},{t:"Menandatanganinya karena hanya sekali ini dan Bambang rekan baik Anda", s:3},{t:"Meminta imbalan terlebih dahulu sebelum mau menandatanganinya", s:2},{t:"Menandatanganinya lalu mengancam akan melaporkannya jika ia tidak menuruti kemauan Anda", s:1}], ex:"Menolak pemalsuan kehadiran dengan tetap memberi jalan keluar yang benar menjunjung integritas; menandatanganinya berarti ikut berbohong dan melanggar disiplin ASN."},
{id:"TKP-2018", q:"Anda dimutasi ke kantor di daerah yang adat istiadatnya sangat berbeda dari daerah asal Anda. Pada minggu pertama, Anda belum memahami banyak kebiasaan setempat. Sikap yang paling tepat adalah ....", opts:[{t:"Aktif belajar dan bertanya kepada rekan setempat tentang adat yang berlaku, serta menyesuaikan sikap agar tidak menyinggung masyarakat dan rekan kerja", s:5},{t:"Mengikuti kebiasaan rekan-rekan setempat sambil perlahan mempelajari adatnya", s:4},{t:"Tetap berperilaku seperti di daerah asal karena sebagai ASN Anda tidak wajib mengikuti adat setempat", s:3},{t:"Menarik diri dari pergaulan agar tidak salah bersikap di lingkungan baru", s:2},{t:"Menganggap adat setempat ketinggalan zaman dan terang-terangan mengkritiknya", s:1}], ex:"Aktif mempelajari dan menghormati adat daerah penugasan menunjukkan adaptabilitas dan penghargaan pada budaya; merendahkan adat setempat merusak hubungan dengan masyarakat yang dilayani."},
{id:"TKP-2019", q:"Program kerja bakti massal membutuhkan koordinasi antara dinas Anda dengan dua dinas lain, tetapi masing-masing dinas menunggu dinas lain bergerak lebih dulu. Sikap yang paling tepat adalah ....", opts:[{t:"Mengambil inisiatif mengundang perwakilan tiap dinas untuk menyusun pembagian peran dan jadwal yang jelas secara musyawarah", s:5},{t:"Menghubungi dinas lain untuk menanyakan kesiapan mereka berkoordinasi", s:4},{t:"Menunggu arahan pimpinan karena koordinasi antar dinas bukan wewenang staf", s:3},{t:"Menjalankan program hanya dengan dinas sendiri agar tidak repot berkoordinasi", s:2},{t:"Menyalahkan dinas lain di depan pimpinan sebagai pihak yang tidak kooperatif", s:1}], ex:"Inisiatif memfasilitasi musyawarah lintas dinas mencerminkan jiwa koordinasi dan kepemimpinan; saling menunggu atau menyalahkan hanya membuat program mangkrak."},
{id:"TKP-2020", q:"Seorang rekan mengajak Anda bergosip tentang keburukan atasan di sela jam istirahat. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan halus dan mengalihkan pembicaraan ke hal positif, serta mengingatkan bahwa menjelekkan pimpinan merusak kekompakan tim", s:5},{t:"Tidak menanggapi ajakan bergosip tersebut dan pergi meninggalkan pembicaraan", s:4},{t:"Mendengarkan saja tanpa ikut berkomentar karena tidak enak menolak rekan", s:3},{t:"Ikut menambahkan cerita keburukan atasan agar terlihat akrab dengan rekan", s:2},{t:"Merekam pembicaraan tersebut lalu melaporkannya ke atasan agar rekan mendapat hukuman", s:1}], ex:"Menolak gosip sekaligus mengingatkan dampaknya menjaga etika dan soliditas tim; ikut bergosip atau menjebak rekan sama-sama merusak kepercayaan."},
{id:"TKP-2021", q:"Panitia acara kantor memesan konsumsi rapat dan ternyata salah satu menunya mengandung bahan yang haram bagi rekan-rekan muslim. Rapat akan dimulai 30 menit lagi. Sikap yang paling tepat adalah ....", opts:[{t:"Segera berkoordinasi dengan panitia untuk memisahkan menu tersebut dan mengusahakan pengganti yang bisa dinikmati semua peserta", s:5},{t:"Memberi tahu rekan-rekan muslim agar menghindari menu tersebut", s:4},{t:"Membiarkan saja karena kesalahan sudah terjadi dan waktu mepet", s:3},{t:"Menyarankan rekan muslim untuk memaklumi karena panitia tidak sengaja", s:2},{t:"Menyalahkan panitia di depan peserta rapat atas keteledoran tersebut", s:1}], ex:"Sigap mencari solusi agar semua peserta terlayani menunjukkan kepedulian dan toleransi; menyalahkan panitia di depan umum tidak menyelesaikan masalah konsumsi."},
{id:"TKP-2022", q:"Tim Anda akan mempresentasikan hasil kerja ke pimpinan daerah. Rudi yang bertugas memaparkan salah satu bagian terlihat sangat gugup dan takut gagal. Sikap yang paling tepat adalah ....", opts:[{t:"Melakukan gladi bersih bersama, memberi masukan membangun, dan meyakinkan Rudi bahwa tim mendukung penuh penampilannya", s:5},{t:"Menawarkan diri bertukar bagian presentasi dengan Rudi agar ia mendapat bagian yang lebih mudah", s:4},{t:"Menyemangati Rudi sekadarnya dan berharap ia bisa mengatasi sendiri", s:3},{t:"Mengusulkan ke ketua tim agar bagian Rudi diambil alih orang lain", s:2},{t:"Mengejek kegugupan Rudi agar ia malu dan terpacu", s:1}], ex:"Mendukung rekan dengan latihan dan keyakinan mencerminkan solidaritas tim; mengejek atau menyingkirkannya justru menghancurkan kepercayaan diri rekan."},
{id:"TKP-2023", q:"Dalam tim Anda ada pegawai senior yang terbiasa cara manual dan pegawai muda yang serba digital, sehingga sering terjadi gesekan soal cara kerja. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan forum berbagi di mana senior membagikan pengalaman dan junior mengajarkan teknologi, sehingga keduanya saling melengkapi", s:5},{t:"Mengajak kedua belah pihak saling memahami kelebihan masing-masing cara kerja", s:4},{t:"Tidak memihak siapa pun dan mengerjakan tugas dengan cara Anda sendiri", s:3},{t:"Mendukung penuh cara digital karena zaman sudah berubah dan cara lama tertinggal", s:2},{t:"Mengadu domba senior dan junior agar salah satunya tersingkir dari tim", s:1}], ex:"Memfasilitasi saling belajar antar generasi mengubah perbedaan menjadi kekuatan tim; mengadu domba menghancurkan kekompakan yang seharusnya dijaga."},
{id:"TKP-2024", q:"Menjelang hari raya, beberapa rekan mengajukan cuti pada tanggal yang sama sehingga pelayanan kantor terancam kosong. Mereka berasal dari agama yang berbeda dengan hari raya yang berdekatan. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan musyawarah penyusunan jadwal piket bergilir yang adil agar semua bisa merayakan hari rayanya tanpa mengorbankan pelayanan", s:5},{t:"Meminta atasan mengatur jadwal cuti agar pelayanan tetap berjalan", s:4},{t:"Mendahulukan cuti rekan yang mengajukan lebih dulu tanpa mempertimbangkan yang lain", s:3},{t:"Menolak semua pengajuan cuti demi kelangsungan pelayanan kantor", s:2},{t:"Memprioritaskan cuti berdasarkan agama mayoritas pegawai kantor", s:1}], ex:"Penjadwalan cuti yang adil melalui musyawarah menghormati hak beribadah semua pemeluk agama; mendahulukan agama mayoritas adalah diskriminasi yang mencederai persatuan."},
{id:"TKP-2025", q:"Anda mendapati Eko sering meminjam laptop kantor yang menjadi tanggung jawab Anda tanpa izin, dan pernah hampir menghilangkan data penting. Sikap yang paling tepat adalah ....", opts:[{t:"Berbicara langsung dengan Eko secara baik-baik, menyampaikan keberatan dan risiko datanya, serta menyepakati aturan pinjam-meminjam yang jelas", s:5},{t:"Menegur Eko agar lain kali meminta izin terlebih dahulu sebelum meminjam", s:4},{t:"Mendiamkan saja karena Eko rekan satu tim dan Anda tidak ingin ribut", s:3},{t:"Menyembunyikan laptop setiap selesai dipakai agar tidak dipinjam Eko lagi", s:2},{t:"Melaporkan Eko ke atasan sebagai pencuri fasilitas kantor", s:1}], ex:"Membicarakan langsung dengan solusi aturan yang jelas menyelesaikan masalah tanpa merusak hubungan; menuduh mencuri atas peminjaman tanpa izin adalah berlebihan dan memfitnah."},
{id:"TKP-2026", q:"Atasan menugaskan tim Anda lembur menyelesaikan laporan, tetapi belum ada kesepakatan siapa mengerjakan bagian apa. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan rapat singkat untuk membagi tugas lembur sesuai kemampuan dan beban masing-masing secara terbuka dan adil", s:5},{t:"Menawarkan diri mengambil bagian yang paling berat agar rekan lain terbantu", s:4},{t:"Menunggu ditunjuk atasan karena pembagian tugas adalah wewenangnya", s:3},{t:"Mengambil bagian yang paling ringan sebelum diambil rekan lain", s:2},{t:"Pura-pura sakit agar terhindar dari tugas lembur", s:1}], ex:"Inisiatif membagi tugas secara terbuka dan adil mencegah konflik dan mempercepat penyelesaian; menghindar dengan pura-pura sakit adalah ketidakjujuran yang membebani tim."},
{id:"TKP-2027", q:"Bulan Ramadan, rapat penting dijadwalkan pukul 12.00 disertai makan siang bersama, padahal sebagian besar peserta sedang berpuasa. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan agar rapat dimajukan atau makan siangnya diganti buka puasa bersama sehingga yang berpuasa tetap nyaman mengikuti rapat", s:5},{t:"Mengusulkan agar sesi makan siang ditiadakan dan rapat dipersingkat", s:4},{t:"Mengikuti jadwal apa adanya karena panitia sudah menetapkan", s:3},{t:"Meminta rekan yang berpuasa untuk membatalkan puasanya demi kelancaran rapat", s:2},{t:"Memboikot rapat tersebut sebagai protes kepada panitia yang tidak peka", s:1}], ex:"Mengusulkan penyesuaian yang menghormati ibadah puasa menunjukkan toleransi beragama; memaksa membatalkan puasa atau memboikot sama-sama tidak mencerminkan kedewasaan."},
{id:"TKP-2028", q:"Atasan memberi instruksi lisan kepada tim, tetapi Anda dan Lestari memahaminya secara berbeda sehingga pekerjaan hampir salah arah. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak Lestari mengklarifikasi ulang instruksi kepada atasan bersama-sama agar tim berjalan dengan pemahaman yang sama", s:5},{t:"Menyamakan pemahaman dengan Lestari terlebih dahulu sebelum melanjutkan pekerjaan", s:4},{t:"Tetap mengerjakan sesuai pemahaman Anda sendiri karena yakin paling benar", s:3},{t:"Menyalahkan Lestari yang salah memahami instruksi atasan", s:2},{t:"Melaporkan ke atasan bahwa Lestari tidak becus memahami perintah sederhana", s:1}], ex:"Klarifikasi bersama ke sumber instruksi mencegah kesalahan kerja tim; berjalan sendiri-sendiri dengan pemahaman berbeda hanya mengulang kekeliruan."},
{id:"TKP-2029", q:"Ayah dari rekan Anda, Fitri, meninggal dunia dan menurut adat keluarganya ada rangkaian upacara duka selama tiga hari. Sikap yang paling tepat adalah ....", opts:[{t:"Mengorganisasi tim untuk melayat bergantian dan menawarkan bantuan tenaga, serta memaklumi ketidakhadirannya selama upacara berlangsung", s:5},{t:"Ikut melayat bersama rekan-rekan sebagai bentuk belasungkawa", s:4},{t:"Mengirim ucapan duka melalui pesan singkat saja", s:3},{t:"Tidak ikut melayat karena adat duka keluarganya berbeda dengan adat Anda", s:2},{t:"Mengeluh karena pekerjaan Fitri jadi terbengkalai selama ia berduka", s:1}], ex:"Melayat dan membantu rekan yang berduka sesuai adatnya adalah wujud empati dan solidaritas; mengeluh soal pekerjaan di saat duka menunjukkan ketidakpekaan."},
{id:"TKP-2030", q:"Atasan meminta pendapat jujur Anda tentang kinerja Wahyu, rekan satu tim yang memang sering lalai. Sikap yang paling tepat adalah ....", opts:[{t:"Menyampaikan penilaian objektif disertai contoh konkret dan saran pembinaan, tanpa melebih-lebihkan keburukannya", s:5},{t:"Menyampaikan apa adanya tentang kelalaian Wahyu kepada atasan", s:4},{t:"Menjawab normatif bahwa kinerja Wahyu baik-baik saja agar tidak bermusuhan", s:3},{t:"Menjelek-jelekkan Wahyu agar ia dipindahkan dari tim Anda", s:2},{t:"Menolak memberi penilaian karena takut dianggap pengkhianat tim", s:1}], ex:"Penilaian objektif yang disertai saran pembinaan membantu atasan dan rekan berkembang; menjelekkan demi menyingkirkan rekan adalah pengkhianatan terhadap tim."},
{id:"TKP-2031", q:"Beberapa rekan sering mengejek logat daerah Intan setiap kali ia berbicara dalam rapat, membuat Intan enggan berpendapat. Sikap yang paling tepat adalah ....", opts:[{t:"Menegur para pengejek dengan tegas namun santun bahwa logat daerah bukan bahan olok-olok, serta mendorong Intan tetap berani berpendapat", s:5},{t:"Menasihati para pengejek secara pribadi agar berhenti mengejek Intan", s:4},{t:"Diam saja karena itu hanya candaan khas pergaulan kantor", s:3},{t:"Ikut tertawa agar tidak dianggap tidak asyik oleh rekan-rekan", s:2},{t:"Menyarankan Intan menghilangkan logatnya agar tidak diejek lagi", s:1}], ex:"Membela rekan dari ejekan berbasis kedaerahan dan memberinya ruang berpendapat menjunjung persatuan; menyuruh korban mengubah identitasnya justru menyalahkan yang tertindas."},
{id:"TKP-2032", q:"Desa tempat Anda bertugas mengadakan gotong royong membersihkan saluran air, dan perangkat desa berharap pegawai kecamatan ikut serta. Sikap yang paling tepat adalah ....", opts:[{t:"Ikut gotong royong bersama warga sebagai bentuk kedekatan dan keteladanan aparat kepada masyarakat", s:5},{t:"Hadir dalam gotong royong tersebut mewakili kantor kecamatan", s:4},{t:"Tidak ikut karena gotong royong adalah urusan warga desa, bukan tugas pegawai kecamatan", s:3},{t:"Hanya datang sebentar untuk berfoto lalu pergi", s:2},{t:"Menolak dengan alasan gotong royong itu kuno dan tidak efisien", s:1}], ex:"Terjun langsung dalam gotong royong menumbuhkan kepercayaan masyarakat pada aparat; merendahkan tradisi kebersamaan warga mengikis wibawa pelayanan publik."},
{id:"TKP-2033", q:"Ketua tim Anda berhalangan hadir saat ada keputusan mendesak yang harus diambil hari itu juga terkait jadwal pelayanan. Sikap yang paling tepat adalah ....", opts:[{t:"Menghubungi ketua tim untuk meminta arahan, dan bila tidak terhubung, bermusyawarah dengan anggota tim mengambil keputusan sementara yang paling aman bagi pelayanan", s:5},{t:"Bermusyawarah dengan anggota tim untuk mengambil keputusan sementara", s:4},{t:"Menunda keputusan sampai ketua tim kembali karena Anda tidak berwenang", s:3},{t:"Mengambil keputusan sendiri tanpa melibatkan anggota tim lain", s:2},{t:"Memanfaatkan ketidakhadiran ketua untuk mengambil alih kepemimpinannya", s:1}], ex:"Tetap berupaya menghubungi pimpinan sambil bermusyawarah menunjukkan tanggung jawab dan kerjasama; mengambil alih wewenang secara sepihak merusak tata kerja tim."},
{id:"TKP-2034", q:"Yudi selalu berusaha menukar tugasnya yang berat dengan tugas ringan milik rekan lain dengan berbagai alasan. Sikap yang paling tepat adalah ....", opts:[{t:"Membicarakannya dalam forum tim agar pembagian tugas ditetapkan transparan dan tidak bisa ditukar seenaknya tanpa persetujuan bersama", s:5},{t:"Menolak saat Yudi meminta bertukar tugas dengan Anda", s:4},{t:"Membiarkannya karena Anda tidak ingin terlibat konflik dengannya", s:3},{t:"Ikut-ikutan meminta tukar tugas ringan seperti yang dilakukan Yudi", s:2},{t:"Menyebarkan bahwa Yudi pemalas dan licik ke seluruh kantor", s:1}], ex:"Menetapkan aturan pembagian tugas yang transparan melalui forum tim menyelesaikan akar masalah; menjelekkan Yudi ke seluruh kantor hanya menyebar kebencian."},
{id:"TKP-2035", q:"Jadwal piket pelayanan Jumat siang membuat rekan-rekan muslim kesulitan membagi waktu dengan shalat Jumat. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan rotasi piket Jumat siang diisi bergantian atau digeser waktunya, sehingga ibadah dan pelayanan sama-sama terjaga", s:5},{t:"Mengusulkan agar petugas piket Jumat siang diberi kelonggaran waktu untuk shalat", s:4},{t:"Menerima jadwal apa adanya karena piket adalah kewajiban", s:3},{t:"Meminta rekan muslim menunaikan shalat Jumat di lain waktu agar piket tidak terganggu", s:2},{t:"Menuntut agar piket Jumat siang dihapuskan sama sekali", s:1}], ex:"Rotasi atau penyesuaian waktu piket menyeimbangkan kewajiban ibadah dan pelayanan publik; menghapus piket justru mengorbankan kepentingan warga."},
{id:"TKP-2036", q:"Usulan Novi dalam rapat ditolak mentah-mentah oleh mayoritas peserta dan ia terlihat sangat kecewa hingga ingin keluar dari kepanitiaan. Sikap yang paling tepat adalah ....", opts:[{t:"Menghampiri Novi, menghargai keberaniannya berpendapat, dan mengajaknya tetap berkontribusi dengan peran lain yang sesuai kemampuannya", s:5},{t:"Meyakinkan Novi bahwa penolakan usulan adalah hal biasa dalam rapat", s:4},{t:"Membiarkan Novi dengan kekecewaannya karena nanti juga reda sendiri", s:3},{t:"Ikut menyalahkan Novi karena usulannya memang tidak realistis", s:2},{t:"Memanfaatkan kekecewaan Novi untuk mengajaknya keluar dari panitia agar posisi Anda aman", s:1}], ex:"Menghargai pendapat yang ditolak dan merangkul kembali rekan yang kecewa menjaga semangat tim; memanfaatkan kekecewaannya untuk menyingkirkannya adalah tindakan licik."},
{id:"TKP-2037", q:"Menjelang akhir tahun, kantor akan memasang dekorasi perayaan. Muncul perbedaan pendapat: sebagian ingin dekorasi Natal, sebagian ingin nuansa Islami. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan dekorasi yang merangkul semua perayaan akhir tahun secara proporsional atau dekorasi netral kebersamaan, diputuskan melalui musyawarah", s:5},{t:"Mengusulkan dekorasi Natal dan Islami dipasang bergantian sesuai waktunya", s:4},{t:"Tidak ikut berpendapat dan mengikuti keputusan mayoritas saja", s:3},{t:"Mendukung dekorasi sesuai agama mayoritas pegawai", s:2},{t:"Menolak semua dekorasi keagamaan dengan alasan kantor harus steril dari agama", s:1}], ex:"Dekorasi inklusif hasil musyawarah menghormati semua keyakinan pegawai; memaksakan agama mayoritas menindas minoritas dan merusak kerukunan kantor."},
{id:"TKP-2038", q:"Data yang dikumpulkan tiap anggota tim untuk laporan triwulan ternyata tidak konsisten satu sama lain sehingga laporannya kacau. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan tim menyepakati format dan definisi data yang baku terlebih dahulu, lalu memverifikasi ulang bersama sebelum laporan disusun", s:5},{t:"Mengumpulkan ulang data bersama tim dengan format yang disamakan", s:4},{t:"Menyusun laporan apa adanya dari data yang tersedia", s:3},{t:"Menyalahkan anggota yang datanya paling tidak konsisten", s:2},{t:"Memalsukan angka agar data terlihat konsisten dan laporan cepat selesai", s:1}], ex:"Menyepakati standar data bersama lalu verifikasi ulang menyelesaikan akar masalah; memalsukan angka adalah pelanggaran integritas yang mencederai akuntabilitas."},
{id:"TKP-2039", q:"Arif selalu datang terlambat ke rapat tim dengan alasan macet, padahal rapat sering tertunda menunggunya. Sikap yang paling tepat adalah ....", opts:[{t:"Membicarakannya baik-baik dengan Arif, mencari tahu kendala sebenarnya, dan menyepakati komitmen waktu bersama seluruh tim", s:5},{t:"Menegur Arif agar berusaha datang tepat waktu demi menghargai rekan lain", s:4},{t:"Membiarkan saja karena menegur bisa membuatnya tersinggung", s:3},{t:"Memulai rapat tanpa menunggu Arif sebagai pelajaran baginya", s:2},{t:"Mengusulkan Arif dikeluarkan dari tim karena tidak disiplin", s:1}], ex:"Dialog empatik disertai komitmen bersama menyelesaikan keterlambatan tanpa merusak hubungan; langsung menuntut pengeluaran dari tim adalah langkah berlebihan tanpa pembinaan."},
{id:"TKP-2040", q:"Kantor rutin mengadakan pengajian setiap Jumat pagi dan Lina yang beragama Kristen merasa tidak nyaman karena selalu ditanya kenapa tidak ikut. Sikap yang paling tepat adalah ....", opts:[{t:"Menegaskan bahwa pengajian bersifat sukarela bagi yang seiman dan tidak seorang pun boleh dipaksa atau dipertanyakan keyakinannya", s:5},{t:"Menjelaskan kepada rekan-rekan agar tidak lagi menanyai Lina soal keikutsertaannya", s:4},{t:"Menyarankan Lina ikut saja sesekali agar tidak ditanya-tanya lagi", s:3},{t:"Ikut menanyai Lina karena penasaran dengan alasannya", s:2},{t:"Mengusulkan Lina dipindahkan ke unit lain agar tidak mengganggu kekhusyukan pengajian", s:1}], ex:"Menegaskan sifat sukarela kegiatan keagamaan melindungi kebebasan berkeyakinan setiap pegawai; memaksa atau menyingkirkan yang beda keyakinan adalah intoleransi."},
{id:"TKP-2041", q:"Tono, rekan satu tim Anda, akan pindah ke unit lain minggu depan dan belum menyerahkan dokumen pekerjaannya yang masih berjalan. Sikap yang paling tepat adalah ....", opts:[{t:"Membantu Tono menyusun berita acara serah terima yang rapi agar tidak ada pekerjaan yang terputus dan tim tidak kebingungan", s:5},{t:"Mengingatkan Tono agar menyelesaikan serah terima sebelum pindah", s:4},{t:"Menunggu Tono berinisiatif sendiri karena itu tanggung jawabnya", s:3},{t:"Membiarkan saja, nanti juga ketahuan sendiri bagian mana yang belum diserahkan", s:2},{t:"Menjelekkan Tono ke unit barunya sebagai pegawai yang tidak bertanggung jawab", s:1}], ex:"Membantu serah terima yang rapi menjamin keberlangsungan kerja tim; menjelekkan rekan yang pindah justru menunjukkan kedengkian pribadi."},
{id:"TKP-2042", q:"Dalam rapat resmi, seorang rekan sesekali menyelipkan bahasa daerahnya sehingga peserta dari daerah lain kesulitan memahami. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan dengan santun agar rapat memakai bahasa Indonesia demi dipahami semua, sambil tetap menghargai bahasa daerah dalam pergaulan santai", s:5},{t:"Meminta rekan tersebut mengulangi penjelasannya dalam bahasa Indonesia", s:4},{t:"Diam saja meski tidak paham agar tidak menyinggung rekan", s:3},{t:"Menertawakan bahasa daerahnya di depan peserta rapat", s:2},{t:"Mengusulkan rekan tersebut tidak diikutsertakan dalam rapat berikutnya", s:1}], ex:"Menggunakan bahasa persatuan dalam forum resmi menjamin komunikasi efektif tanpa merendahkan bahasa daerah; menertawakannya adalah penghinaan terhadap budaya rekan."},
{id:"TKP-2043", q:"Sore ini datang tugas mendadak dari pimpinan yang harus selesai malam ini juga, padahal semua anggota tim sudah lelah. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak tim membagi tugas secara adil sesuai sisa energi dan kemampuan, serta memastikan tidak ada yang menanggung beban sendirian", s:5},{t:"Ikut lembur bersama tim menyelesaikan tugas tersebut", s:4},{t:"Mengerjakan bagian Anda saja lalu pulang", s:3},{t:"Berpura-pura ada keperluan mendesak agar bisa pulang lebih dulu", s:2},{t:"Menolak tugas tersebut dengan alasan sudah di luar jam kerja", s:1}], ex:"Pembagian tugas lembur yang adil menunjukkan solidaritas dan tanggung jawab tim; berpura-pura berhalangan adalah ketidakjujuran yang menambah beban rekan."},
{id:"TKP-2044", q:"Program pemberdayaan masyarakat di wilayah kerja Anda akan lebih diterima bila melibatkan tokoh adat setempat, tetapi sebagian tim menganggap itu tidak perlu. Sikap yang paling tepat adalah ....", opts:[{t:"Menjelaskan kepada tim bahwa melibatkan tokoh adat adalah strategi kearifan lokal yang mempercepat penerimaan program oleh masyarakat", s:5},{t:"Mengusulkan agar tokoh adat dilibatkan sebagai penasihat program", s:4},{t:"Mengikuti pendapat mayoritas tim yang menganggap tokoh adat tidak perlu", s:3},{t:"Menjalankan program tanpa melibatkan siapa pun dari masyarakat", s:2},{t:"Mengejek tim yang mengusulkan pelibatan tokoh adat sebagai kolot", s:1}], ex:"Memanfaatkan kearifan lokal melalui tokoh adat memperkuat legitimasi program di masyarakat; mengabaikan struktur adat setempat berisiko menimbulkan penolakan warga."},
{id:"TKP-2045", q:"Saat Anda memberi masukan tentang hasil kerjanya, Galih tersinggung dan bersikap defensif, menuduh Anda iri padanya. Sikap yang paling tepat adalah ....", opts:[{t:"Tetap tenang, menegaskan bahwa masukan bertujuan membangun, dan mengajak Galih mendiskusikan solusinya secara objektif", s:5},{t:"Meminta maaf bila cara penyampaian Anda menyinggung, lalu menyampaikan masukan dengan lebih halus", s:4},{t:"Tidak pernah lagi memberi masukan kepada Galih agar hubungan tetap baik", s:3},{t:"Membalas menuduh Galih tidak bisa menerima kritik", s:2},{t:"Menyebarkan bahwa Galih anti kritik ke rekan-rekan lain", s:1}], ex:"Tetap tenang dan fokus pada solusi saat rekan defensif menunjukkan kedewasaan berkomunikasi; membalas tuduhan hanya memperpanjang konflik."},
{id:"TKP-2046", q:"Beredar kabar bohong bernuansa SARA di grup WhatsApp kantor yang menyudutkan salah satu kelompok agama. Sikap yang paling tepat adalah ....", opts:[{t:"Mengingatkan di grup agar tidak menyebarkan kabar yang belum terverifikasi, serta mengajak rekan menjaga kerukunan antarumat beragama", s:5},{t:"Tidak meneruskan kabar tersebut dan menghapusnya dari ponsel Anda", s:4},{t:"Mengabaikannya karena bukan Anda yang menyebarkan", s:3},{t:"Ikut meneruskannya ke grup keluarga karena isinya menarik", s:2},{t:"Menambahi kabar tersebut dengan komentar provokatif agar ramai", s:1}], ex:"Aktif mengingatkan bahaya hoaks SARA melindungi kerukunan dan nama baik instansi; ikut menyebarkan berarti menjadi bagian dari perpecahan."},
{id:"TKP-2047", q:"Dani meminta Anda mengerjakan seluruh tugas laporannya dengan iming-iming akan mentraktir Anda makan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas dan menyarankan Dani mengerjakan sendiri sambil menawarkan bantuan secukupnya agar ia belajar bertanggung jawab", s:5},{t:"Menolak permintaan Dani karena itu bukan kewajiban Anda", s:4},{t:"Mengerjakannya karena imbalannya menggiurkan dan Dani rekan baik", s:3},{t:"Menerima dengan syarat imbalan ditambah", s:2},{t:"Menerima lalu melaporkan Dani ke atasan agar ia dihukum dan Anda terlihat berjasa", s:1}], ex:"Menolak mengerjakan tugas orang lain dengan tetap menawarkan bimbingan menegakkan tanggung jawab individu; menerima imbalan demi mengerjakan tugas rekan adalah gratifikasi terselubung."},
{id:"TKP-2048", q:"Upacara adat tahunan desa tempat Anda bertugas jatuh pada hari kerja dan perangkat desa meminta pegawai kecamatan hadir sebagai bentuk penghormatan. Sikap yang paling tepat adalah ....", opts:[{t:"Berkoordinasi dengan atasan agar perwakilan pegawai bisa hadir bergantian tanpa mengganggu pelayanan, sebagai penghargaan pada adat masyarakat", s:5},{t:"Menghadiri upacara adat tersebut sebagai perwakilan kantor", s:4},{t:"Tidak hadir karena hari kerja harus diisi dengan tugas kantor", s:3},{t:"Hadir hanya untuk formalitas lalu segera kembali tanpa mengikuti rangkaian acara", s:2},{t:"Menolak mentah-mentah karena adat desa bukan urusan pegawai kecamatan", s:1}], ex:"Menghadirkan perwakilan secara bergantian menyeimbangkan tugas dinas dan penghormatan pada adat; menolak mentah-mentah melukai hubungan baik dengan masyarakat."},
{id:"TKP-2049", q:"Tim Anda kedatangan anggota baru, Sinta, yang menggunakan kursi roda. Saat pembagian tugas lapangan, muncul kebingungan. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak tim menyusun pembagian tugas yang memanfaatkan kelebihan Sinta, misalnya analisis data dan koordinasi, sehingga ia berkontribusi optimal", s:5},{t:"Memberi Sinta tugas-tugas administratif yang bisa dikerjakan dari kantor", s:4},{t:"Membiarkan Sinta menentukan sendiri tugas apa yang sanggup ia kerjakan", s:3},{t:"Tidak memberi Sinta tugas apa pun karena kasihan padanya", s:2},{t:"Mengusulkan Sinta dipindahkan karena tim lapangan butuh yang fisik prima", s:1}], ex:"Pembagian tugas berbasis kemampuan memastikan setiap anggota berkontribusi bermakna; menyingkirkan penyandang disabilitas adalah diskriminasi yang melanggar asas kesetaraan."},
{id:"TKP-2050", q:"Bella yang beragama Konghucu merayakan Imlek dan membagikan kue keranjang kepada seluruh tim termasuk Anda. Sikap yang paling tepat adalah ....", opts:[{t:"Menerima dengan senang hati dan mengucapkan selamat merayakan, sebagai penghargaan atas kebersamaan dalam keberagaman", s:5},{t:"Menerima pemberian Bella dan mengucapkan terima kasih", s:4},{t:"Menolak secara halus karena tidak merayakan Imlek", s:3},{t:"Menerima tetapi membuangnya diam-diam karena tidak biasa memakannya", s:2},{t:"Mengejek tradisi bagi-bagi kue keranjang sebagai pemborosan", s:1}], ex:"Menerima dan menghargai perayaan hari besar rekan lintas agama mempererat persaudaraan; merendahkan tradisinya mencederai semangat toleransi."},{id:"TKP-2051", q:"Rapat tim Anda alot karena dua kubu bersikukuh pada usulannya masing-masing. Seorang rekan mengusulkan voting agar cepat selesai. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan agar musyawarah dilanjutkan dengan fasilitasi yang baik untuk mencari titik temu, karena mufakat lebih mengikat daripada voting", s:5},{t:"Mendukung voting sebagai jalan keluar yang demokratis", s:4},{t:"Mengikuti apa pun keputusan mayoritas tanpa peduli caranya", s:3},{t:"Mendukung kubu yang usulannya menguntungkan Anda", s:2},{t:"Keluar dari rapat karena jenuh dengan perdebatan yang tidak selesai", s:1}], ex:"Mengupayakan musyawarah mufakat terlebih dahulu menjunjung budaya demokrasi Pancasila; langsung voting tanpa dialog mengabaikan suara minoritas."},
{id:"TKP-2052", q:"Rekan Anda, Nita, tidak bersedia berjabat tangan dengan lawan jenis karena keyakinan agamanya. Seorang tamu pria tersinggung saat tangannya tidak disambut. Sikap yang paling tepat adalah ....", opts:[{t:"Menjelaskan dengan ramah kepada tamu bahwa itu keyakinan agama Nita yang harus dihormati, sambil menawarkan cara menyapa alternatif yang sopan", s:5},{t:"Meminta maaf kepada tamu atas ketidaknyamanan yang terjadi", s:4},{t:"Diam saja karena itu urusan pribadi Nita dengan tamunya", s:3},{t:"Menyarankan Nita untuk fleksibel saja berjabat tangan demi profesionalitas", s:2},{t:"Mengejek Nita di depan tamu sebagai orang yang kolot", s:1}], ex:"Menjembatani kesalahpahaman dengan penjelasan yang menghormati keyakinan rekan menunjukkan toleransi; memaksa rekan melanggar keyakinannya adalah intoleransi."},
{id:"TKP-2053", q:"Hadi sangat mahir mengolah data, tetapi enggan berbagi ilmunya kepada tim dengan alasan takut tersaingi. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan program berbagi pengetahuan rutin di tim dan meyakinkan Hadi bahwa berbagi ilmu justru meningkatkan nilainya sebagai anggota tim", s:5},{t:"Meminta Hadi mengajari Anda secara pribadi di luar jam kerja", s:4},{t:"Belajar sendiri dari internet tanpa melibatkan Hadi", s:3},{t:"Membiarkan Hadi dengan sikapnya karena itu haknya", s:2},{t:"Menyebarkan bahwa Hadi pelit ilmu agar ia dikucilkan tim", s:1}], ex:"Membangun budaya berbagi pengetahuan memperkuat kapasitas seluruh tim; mengucilkan rekan yang enggan berbagi tidak menyelesaikan masalah."},
{id:"TKP-2054", q:"Tim Anda dinas luar ke daerah terpencil selama tiga hari. Jadwal kegiatan padat hingga menyulitkan rekan-rekan menunaikan ibadah tepat waktu. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan penyesuaian jadwal kegiatan dengan memberi jeda waktu ibadah yang cukup bagi semua pemeluk agama", s:5},{t:"Meminta ketua tim memberi kelonggaran waktu ibadah di sela kegiatan", s:4},{t:"Mengikuti jadwal apa adanya dan menunaikan ibadah sebisanya", s:3},{t:"Menyarankan rekan-rekan menggabungkan saja semua ibadahnya di malam hari", s:2},{t:"Memprotes keras panitia dinas luar di depan peserta lain", s:1}], ex:"Menyesuaikan jadwal dinas agar tidak menghalangi ibadah menunjukkan penghormatan pada keyakinan; memprotes dengan emosi merusak kekompakan tim di lapangan."},
{id:"TKP-2055", q:"Keputusan yang sudah disepakati dalam rapat tim ternyata dibatalkan sepihak oleh Bagus di lapangan dengan alasan lebih praktis. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak Bagus bermusyawarah kembali bersama tim untuk mengevaluasi keputusannya secara terbuka dan menyepakati langkah resmi", s:5},{t:"Menegur Bagus agar tidak mengulangi pembatalan sepihak keputusan bersama", s:4},{t:"Mengikuti saja keputusan Bagus di lapangan agar pekerjaan tidak terhambat", s:3},{t:"Melaporkan Bagus ke atasan sebagai pembangkang keputusan rapat", s:2},{t:"Menyebarkan ke tim lain bahwa Bagus tidak bisa dipercaya memegang kesepakatan", s:1}], ex:"Membawa kembali ke musyawarah tim menegakkan komitmen kolektif; langsung menuduh membangkang tanpa dialog menutup ruang klarifikasi."},
{id:"TKP-2056", q:"Rekan Anda, Ratna, akan menikah dengan adat Minang yang rangkaian acaranya cukup panjang dan ia mengundang seluruh tim. Sikap yang paling tepat adalah ....", opts:[{t:"Menghadiri undangan dan mengikuti prosesi adat dengan hormat sebagai bentuk penghargaan pada budaya Minang", s:5},{t:"Menghadiri resepsinya sebagai dukungan kepada Ratna", s:4},{t:"Memberi kado dan ucapan selamat tanpa hadir karena tidak paham adat Minang", s:3},{t:"Menolak hadir dengan alasan sibuk padahal tidak tertarik adat daerah lain", s:2},{t:"Berkomentar bahwa adat Minang terlalu rumit dan menghabiskan biaya", s:1}], ex:"Menghadiri dan menghormati prosesi adat pernikahan rekan mempererat tali persaudaraan lintas budaya; merendahkan adat suku lain bertentangan dengan Bhinneka Tunggal Ika."},
{id:"TKP-2057", q:"Jadwal jaga UGD puskesmas disusun bergilir, tetapi Putri sering meminta tukar jadwal dengan alasan pribadi hingga bebannya menumpuk pada Anda. Sikap yang paling tepat adalah ....", opts:[{t:"Berbicara terbuka dengan Putri dan mengusulkan batas tukar jadwal yang wajar disepakati tim agar beban terbagi adil", s:5},{t:"Menolak permintaan tukar jadwal Putri berikutnya dengan tegas", s:4},{t:"Terus menerima tukar jadwal karena tidak enak menolak rekan", s:3},{t:"Ikut meminta tukar jadwal seenaknya seperti yang dilakukan Putri", s:2},{t:"Melaporkan Putri ke kepala puskesmas sebagai pegawai manja", s:1}], ex:"Menyepakati batas tukar jadwal yang adil melalui dialog menjaga kekompakan tim jaga; terus mengalah tanpa batas hanya menumpuk beban pada diri sendiri."},
{id:"TKP-2058", q:"Kantor Anda hanya memiliki satu mushola kecil yang dipakai bergantian oleh banyak pegawai setiap waktu shalat. Sering terjadi antrean dan keterlambatan kembali bekerja. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan penjadwalan penggunaan mushola bergilir per unit dan pengajuan perluasan fasilitas ibadah kepada pimpinan", s:5},{t:"Mengatur kesepakatan tidak tertulis dengan rekan agar bergantian memakai mushola", s:4},{t:"Tetap antre seperti biasa meski sering terlambat kembali bekerja", s:3},{t:"Shalat di rumah saja sepulang kerja agar tidak antre", s:2},{t:"Memprotes pengelola gedung karena tidak menyediakan fasilitas ibadah yang layak", s:1}], ex:"Mengusulkan solusi sistemik berupa penjadwalan dan perluasan fasilitas menyeimbangkan ibadah dan disiplin kerja; sekadar protes tanpa usulan tidak menyelesaikan antrean."},
{id:"TKP-2059", q:"Pimpinan meminta tim Anda lembur akhir pekan menyelesaikan laporan, tetapi dua anggota tim keberatan karena sudah ada janji keluarga. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan pembagian lembur bergiliran atau sistem piket agar yang berhalangan bisa digantikan tanpa memaksa", s:5},{t:"Meminta pimpinan mempertimbangkan ulang urgensi lembur tersebut", s:4},{t:"Memaksa semua anggota ikut lembur karena perintah pimpinan mutlak", s:3},{t:"Ikut keberatan dan menolak lembur bersama dua rekan tersebut", s:2},{t:"Melaporkan dua rekan yang keberatan sebagai pembangkang perintah", s:1}], ex:"Mencari skema lembur yang manusiawi melalui musyawarah menyeimbangkan tugas dan kehidupan keluarga; memaksa atau melaporkan rekan merusak kepercayaan tim."},
{id:"TKP-2060", q:"Acara buka puasa bersama kantor dihadiri pula rekan-rekan non-muslim yang ikut membantu persiapan. Saat hidangan disajikan, muncul kebingungan siapa boleh makan duluan. Sikap yang paling tepat adalah ....", opts:[{t:"Menjelaskan dengan ramah bahwa yang berpuasa menunggu azan magrib, sementara rekan non-muslim dipersilakan menikmati hidangan lebih dulu sebagai tamu yang dihormati", s:5},{t:"Mempersilakan rekan non-muslim makan terlebih dahulu sambil menunggu waktu berbuka", s:4},{t:"Menyuruh semua menunggu azan magrib agar seragam", s:3},{t:"Membiarkan masing-masing makan sesukanya tanpa penjelasan", s:2},{t:"Menyindir rekan non-muslim yang makan duluan sebagai tidak menghargai yang puasa", s:1}], ex:"Memberi penjelasan ramah yang menghormati kedua belah pihak mencerminkan indahnya toleransi; menyindir tamu yang berbeda keyakinan justru merusak suasana kebersamaan."},
{id:"TKP-2061", q:"File laporan bersama yang dikerjakan tim di komputer kantor tiba-tiba rusak dan tidak bisa dibuka, padahal deadline besok pagi. Sikap yang paling tepat adalah ....", opts:[{t:"Segera mengoordinasikan tim membagi ulang bagian yang hilang untuk dikerjakan bersama-sama lembur, sambil membuat cadangan ganda ke depannya", s:5},{t:"Mengajak tim bekerja sama menyusun ulang laporan tersebut", s:4},{t:"Menunggu ada yang berinisiatif memperbaikinya terlebih dahulu", s:3},{t:"Menyalahkan rekan yang terakhir memakai komputer tersebut", s:2},{t:"Melaporkan ke atasan bahwa laporan tidak bisa selesai karena komputer rusak", s:1}], ex:"Sigap mengoordinasikan kerja ulang bersama menunjukkan tanggung jawab kolektif; menyalahkan atau pasrah pada keadaan mengabaikan kewajiban menyelesaikan tugas."},
{id:"TKP-2062", q:"Seorang rekan meyakini hari tertentu tidak baik untuk mengadakan rapat penting menurut kepercayaan yang dianutnya, dan meminta jadwal digeser. Sikap yang paling tepat adalah ....", opts:[{t:"Menghormati keyakinannya dan mengusulkan penggeseran jadwal selama tidak mengganggu tenggat, sebagai bentuk toleransi", s:5},{t:"Menyetujui penggeseran jadwal agar rekan merasa nyaman", s:4},{t:"Menolak karena jadwal rapat tidak bisa diatur oleh kepercayaan pribadi", s:3},{t:"Mengejek kepercayaannya sebagai takhayul di depan peserta rapat", s:2},{t:"Mengusulkan rekan tersebut tidak usah ikut rapat saja", s:1}], ex:"Menghormati keyakinan rekan selama tidak merugikan jadwal menunjukkan toleransi berkepercayaan; mengejeknya adalah penghinaan terhadap kebebasan berkeyakinan."},
{id:"TKP-2063", q:"Dian, rekan satu tim Anda, akhir-akhir ini sering melamun dan pekerjaannya menurun drastis. Ia mengaku sedang ada masalah keluarga. Sikap yang paling tepat adalah ....", opts:[{t:"Mendengarkan keluhannya dengan empati, menawarkan bantuan meringankan bebannya, dan menyarankan ia berkonsultasi bila masalahnya berat", s:5},{t:"Menawarkan bantuan mengerjakan sebagian tugasnya selama ia kesulitan", s:4},{t:"Membiarkannya karena masalah keluarga adalah urusan pribadi", s:3},{t:"Menegurnya agar tidak mencampuradukkan masalah pribadi dengan pekerjaan", s:2},{t:"Menyebarkan masalah keluarga Dian ke rekan lain sebagai bahan gosip", s:1}], ex:"Empati dan bantuan konkret pada rekan yang kesulitan mencerminkan kepedulian tim; menyebarkan masalah pribadinya adalah pengkhianatan kepercayaan."},
{id:"TKP-2064", q:"Pada HUT kantor, tiap unit diminta menampilkan kesenian daerah. Unit Anda anggotanya berasal dari berbagai suku. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan kolaborasi tarian atau musik yang memadukan unsur beberapa daerah sebagai simbol persatuan dalam keberagaman", s:5},{t:"Memilih satu kesenian daerah yang disepakati bersama untuk ditampilkan", s:4},{t:"Menyerahkan sepenuhnya kepada ketua unit untuk menentukan", s:3},{t:"Bersikeras menampilkan kesenian daerah asal Anda sendiri", s:2},{t:"Menolak tampil dengan alasan tidak ada yang bisa menari", s:1}], ex:"Kolaborasi lintas budaya dalam satu penampilan mewujudkan Bhinneka Tunggal Ika secara nyata; memaksakan satu daerah mengabaikan keberagaman anggota tim."},
{id:"TKP-2065", q:"Prestasi Yoga, pegawai termuda di tim, mendapat apresiasi pimpinan. Seorang senior terlihat sinis dan meremehkannya. Sikap yang paling tepat adalah ....", opts:[{t:"Tetap memberi selamat kepada Yoga secara tulus dan mengajak senior melihat prestasi sebagai motivasi, bukan ancaman", s:5},{t:"Memberi selamat kepada Yoga atas prestasinya", s:4},{t:"Diam saja agar tidak terseret konflik senior-junior", s:3},{t:"Ikut meremehkan Yoga agar tetap akrab dengan senior", s:2},{t:"Menghasut Yoga agar tidak menghormati senior yang iri tersebut", s:1}], ex:"Mengapresiasi prestasi secara tulus tanpa memandang senioritas menumbuhkan budaya merit; ikut meremehkan demi menjilat senior merusak keadilan."},
{id:"TKP-2066", q:"Wilayah kerja Anda masyarakatnya sangat menjunjung tata krama dan kesopanan dalam berkomunikasi. Sikap yang paling tepat dalam memberikan pelayanan adalah ....", opts:[{t:"Menyesuaikan gaya komunikasi menjadi lebih santun dan sabar mengikuti adat setempat agar warga merasa dihargai", s:5},{t:"Berbicara dengan ramah dan sopan kepada setiap warga yang dilayani", s:4},{t:"Melayani seperti biasa karena prosedur pelayanan sudah baku", s:3},{t:"Menegur warga yang dianggap terlalu bertele-tele dalam menyampaikan keperluan", s:2},{t:"Menganggap tata krama setempat menghambat efisiensi pelayanan", s:1}], ex:"Menyesuaikan etika komunikasi dengan kearifan lokal meningkatkan kepercayaan warga pada pelayanan; mengabaikan adat setempat menciptakan jarak antara aparat dan masyarakat."},
{id:"TKP-2067", q:"Lembur mendadak dijadwalkan hingga malam, tetapi Imam keberatan karena harus menunaikan ibadah dan kewajibannya di malam hari. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan agar Imam diberi giliran lembur di waktu lain atau tugas yang bisa diselesaikan lebih awal, tanpa mengurangi total bebannya", s:5},{t:"Meminta pimpinan memberi keringanan jadwal lembur bagi Imam", s:4},{t:"Meminta Imam tetap ikut lembur karena tugas dinas tidak bisa ditawar", s:3},{t:"Menyarankan Imam mengabaikan saja kewajibannya malam itu", s:2},{t:"Mengejek Imam sebagai pegawai yang tidak loyal pada tim", s:1}], ex:"Mencarikan skema pengganti yang adil menghormati kewajiban ibadah tanpa mengurangi tanggung jawab; memaksa atau mengejeknya adalah intoleransi berkedok loyalitas."},
{id:"TKP-2068", q:"Tim Anda gagal meraih predikat unit terbaik tahun ini. Dalam rapat evaluasi, suasana tegang dan mulai ada yang saling tuding. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak tim memetakan kekurangan secara jujur tanpa menuding individu, lalu menyusun target perbaikan yang disepakati bersama", s:5},{t:"Mengakui kekurangan tim secara umum dan fokus membahas perbaikan", s:4},{t:"Diam dan menunggu rapat selesai karena tidak ingin disalahkan", s:3},{t:"Menuding anggota yang kinerjanya paling buruk sebagai penyebab kegagalan", s:2},{t:"Menyatakan keluar dari tim karena malu menjadi bagian tim yang gagal", s:1}], ex:"Evaluasi jujur berorientasi perbaikan tanpa kambing hitam membangun tim yang tangguh; menuding atau kabur saat gagal menunjukkan mentalitas yang lemah."},
{id:"TKP-2069", q:"Panitia peringatan hari besar keagamaan di kantor membutuhkan ketua, dan Salsa yang berbeda agama dengan mayoritas panitia dinilai paling cakap berorganisasi. Sikap yang paling tepat adalah ....", opts:[{t:"Mendukung Salsa menjadi ketua karena kemampuan, sambil memastikan seluruh kebutuhan ritual keagamaan ditangani yang seiman", s:5},{t:"Mendukung penunjukan Salsa dan membantunya dalam kepanitiaan", s:4},{t:"Tidak berpendapat karena khawatir dianggap tidak menghargai agama sendiri", s:3},{t:"Menolak Salsa menjadi ketua karena beda agama dengan acara yang dirayakan", s:2},{t:"Memboikot acara tersebut bila Salsa tetap ditunjuk", s:1}], ex:"Menilai kepemimpinan dari kemampuan bukan agama adalah toleransi yang dewasa; menolak karena perbedaan keyakinan menumbuhkan diskriminasi."},
{id:"TKP-2070", q:"Tim Anda bekerja sama dengan vendor untuk pengadaan barang, tetapi vendor sering terlambat memenuhi janji sehingga pekerjaan tim terhambat. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak tim menyusun teguran resmi berjenjang kepada vendor disertai tenggat jelas, sesuai kontrak yang disepakati", s:5},{t:"Menghubungi vendor untuk menanyakan kendala dan meminta komitmen jadwal baru", s:4},{t:"Menunggu vendor memenuhi janjinya karena sudah dikontrak", s:3},{t:"Mencari vendor lain diam-diam tanpa pemberitahuan", s:2},{t:"Menyuap vendor agar pekerjaannya diprioritaskan", s:1}], ex:"Peneguran resmi sesuai kontrak menunjukkan profesionalitas tim dalam bermitra; menyuap vendor adalah gratifikasi yang melanggar integritas."},
{id:"TKP-2071", q:"Rekan baru Anda mengenakan jilbab syar'i yang menutupi hingga dada. Seorang rekan berkomentar bahwa penampilannya tidak sesuai citra modern kantor. Sikap yang paling tepat adalah ....", opts:[{t:"Menegaskan bahwa busana sesuai keyakinan adalah hak setiap pegawai selama rapi dan sesuai aturan seragam, serta menegur komentar tersebut", s:5},{t:"Membela rekan baru bahwa penampilannya tidak melanggar aturan", s:4},{t:"Diam saja karena tidak ingin terlibat urusan penampilan orang", s:3},{t:"Ikut menyarankan rekan baru berpakaian lebih modern agar diterima", s:2},{t:"Ikut mengejek penampilannya agar akrab dengan rekan yang berkomentar", s:1}], ex:"Membela hak berbusana sesuai keyakinan adalah wujud toleransi dan penghormatan; ikut mengejek berarti merendahkan keyakinan rekan."},
{id:"TKP-2072", q:"Beberapa rekan mengajak Anda mogok kerja sebagai protes atas kebijakan pimpinan yang dianggap tidak adil. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak ajakan mogok dan mengusulkan agar aspirasi disampaikan melalui jalur resmi seperti musyawarah atau serikat pekerja", s:5},{t:"Tidak ikut mogok dan tetap bekerja seperti biasa", s:4},{t:"Ikut-ikutan mogok agar tidak dianggap pengkhianat rekan", s:3},{t:"Ikut mogok sambil menyebarkan provokasi ke unit lain", s:2},{t:"Memanfaatkan mogok untuk menuntut kenaikan jabatan pribadi", s:1}], ex:"Menyalurkan aspirasi melalui jalur resmi menjunjung demokrasi sekaligus menjaga pelayanan publik; mogok kerja merugikan masyarakat yang dilayani."},
{id:"TKP-2073", q:"Rapat tim Anda dihadiri rekan tuna rungu yang berkomunikasi dengan bahasa isyarat. Ia tampak kesulitan mengikuti pembahasan yang cepat. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan agar rapat berjalan lebih tertata dengan ringkasan tertulis tiap poin, sehingga rekan tersebut dapat mengikuti penuh", s:5},{t:"Meminta notulen rapat dibagikan segera setelah rapat selesai", s:4},{t:"Membiarkannya karena ia pasti sudah terbiasa dengan kondisinya", s:3},{t:"Berbicara lebih keras agar ia bisa membaca gerak bibir", s:2},{t:"Mengusulkan ia tidak perlu diikutsertakan dalam rapat-rapat penting", s:1}], ex:"Menyesuaikan mekanisme rapat agar inklusif memastikan setiap anggota berkontribusi; menyingkirkannya dari rapat adalah diskriminasi terhadap penyandang disabilitas."},
{id:"TKP-2074", q:"Kantor mengadakan syukuran atas capaian kinerja dan seluruh pegawai diundang. Muncul usul agar acara diisi tausiyah satu agama saja. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan agar syukuran diisi doa bersama yang universal atau sambutan yang menghargai semua keyakinan pegawai", s:5},{t:"Mengusulkan tausiyah diganti dengan ramah tamah dan makan bersama", s:4},{t:"Mengikuti saja usul yang ada demi kelancaran acara", s:3},{t:"Mendukung tausiyah satu agama karena mayoritas pegawai seiman", s:2},{t:"Menolak hadir bila acara tidak sesuai dengan keyakinan Anda", s:1}], ex:"Syukuran bersama yang inklusif merayakan capaian seluruh pegawai tanpa kecuali; memaksakan satu agama mengabaikan keberagaman tim."},
{id:"TKP-2075", q:"Rizky selalu menunda mengerjakan bagiannya hingga detik-detik terakhir, membuat tim lain cemas dan sering lembur mendadak. Sikap yang paling tepat adalah ....", opts:[{t:"Berbicara dengan Rizky untuk memahami penyebabnya, lalu menyepakati tonggak waktu antara bersama tim agar pekerjaannya terpantau", s:5},{t:"Menegur Rizky agar mengubah kebiasaannya demi ketenangan tim", s:4},{t:"Mengerjakan bagian Rizky lebih awal agar tim tidak cemas menunggu", s:3},{t:"Membiarkannya karena pada akhirnya pekerjaannya selalu selesai", s:2},{t:"Mengusulkan Rizky diberi sanksi berat agar jera", s:1}], ex:"Menyepakati tonggak waktu yang terpantau menyelesaikan kebiasaan menunda secara sistemik; langsung menuntut sanksi berat tanpa pembinaan adalah berlebihan."},
{id:"TKP-2076", q:"Hari Raya Nyepi tiba dan Made, rekan Anda yang beragama Hindu, akan menjalankan Catur Brata Penyepian termasuk tidak bekerja. Sikap yang paling tepat adalah ....", opts:[{t:"Menghormati sepenuhnya pelaksanaan Nyepi oleh Made dan mengatur ulang pembagian tugas tim selama ia beribadah", s:5},{t:"Memberi selamat Hari Raya Nyepi dan memaklumi ketidakhadirannya", s:4},{t:"Meminta Made tetap masuk kerja karena Nyepi bukan libur nasional di daerah Anda", s:3},{t:"Mengejek ritual Nyepi sebagai hal yang aneh", s:2},{t:"Melaporkan Made sebagai mangkir kerja pada hari Nyepi", s:1}], ex:"Menghormati dan menyesuaikan tugas selama hari suci rekan adalah toleransi beragama yang nyata; merendahkan ritualnya melukai kerukunan umat beragama."},
{id:"TKP-2077", q:"Tim Anda menerima uang lembur kolektif, tetapi belum ada kesepakatan cara membaginya. Sebagian ingin dibagi rata, sebagian ingin sesuai kontribusi. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan musyawarah untuk menyepakati formula pembagian yang adil dan transparan, didokumentasikan agar tidak jadi polemik", s:5},{t:"Mengusulkan pembagian berdasarkan catatan kehadiran lembur masing-masing", s:4},{t:"Menerima saja berapa pun bagian yang diberikan", s:3},{t:"Menuntut bagian lebih besar karena merasa paling banyak bekerja", s:2},{t:"Mengambil diam-diam sebagian uang sebelum dibagikan", s:1}], ex:"Kesepakatan transparan hasil musyawarah mencegah konflik soal uang; mengambil diam-diam adalah penggelapan yang melanggar kejujuran."},
{id:"TKP-2078", q:"Seorang rekan dari suku minoritas di kantor Anda sering dikucilkan dalam pergaulan, tidak pernah diajak makan siang bersama. Sikap yang paling tepat adalah ....", opts:[{t:"Aktif mengajaknya bergabung dalam kegiatan tim dan menegur halus rekan yang mengucilkannya karena perbedaan suku", s:5},{t:"Mengajaknya makan siang bersama Anda agar ia tidak merasa sendiri", s:4},{t:"Diam saja karena itu urusan pergaulan pribadi masing-masing", s:3},{t:"Ikut mengucilkannya agar tidak dijauhi kelompok mayoritas", s:2},{t:"Menyebarkan bahwa ia memang sulit bergaul karena sukunya tertutup", s:1}], ex:"Aktif merangkul dan menegur pengucilan berbasis suku menegakkan persatuan; ikut mengucilkan berarti ikut melakukan diskriminasi."},
{id:"TKP-2079", q:"Dalam rapat daring, Bambang tidak pernah menyalakan kamera dan jarang merespons saat ditanya, padahal ia penanggung jawab salah satu agenda. Sikap yang paling tepat adalah ....", opts:[{t:"Menghubungi Bambang secara pribadi menanyakan kendalanya dan menyepakati komitmen keaktifan dalam rapat daring berikutnya", s:5},{t:"Menegur Bambang agar lebih aktif dalam rapat daring", s:4},{t:"Membiarkannya karena rapat daring memang sulit dikontrol", s:3},{t:"Melaporkan Bambang ke atasan sebagai pegawai yang tidak serius", s:2},{t:"Mempermalukannya dengan menyindir di depan peserta rapat daring", s:1}], ex:"Menanyakan kendala secara pribadi lalu menyepakati komitmen menyelesaikan masalah tanpa mempermalukan; menyindir di depan umum merusak martabat rekan."},
{id:"TKP-2080", q:"Anda diminta atasan menulis surat rekomendasi untuk Winda, tetapi Anda tahu kinerjanya biasa saja dan ia meminta Anda melebih-lebihkannya. Sikap yang paling tepat adalah ....", opts:[{t:"Menulis rekomendasi secara jujur sesuai fakta kinerja Winda dan menolak melebih-lebihkan, sambil menjelaskan hal ini kepadanya", s:5},{t:"Menulis rekomendasi apa adanya tanpa tambahan yang tidak benar", s:4},{t:"Menulis sesuai permintaan Winda karena tidak enak menolak rekan", s:3},{t:"Menolak menulis rekomendasi sama sekali", s:2},{t:"Menulis rekomendasi yang melebih-lebihkan lalu meminta imbalan dari Winda", s:1}], ex:"Rekomendasi yang jujur menjaga integritas penilaian; melebih-lebihkan demi imbalan adalah kebohongan yang merusak kepercayaan."},
{id:"TKP-2081", q:"Banjir melanda kawasan tempat tinggal warga binaan Anda. Perangkat desa mengajak pegawai kecamatan gotong royong membantu evakuasi. Sikap yang paling tepat adalah ....", opts:[{t:"Terjun langsung membantu evakuasi dan mengoordinasikan tim kecamatan agar bantuan tersalurkan cepat dan tepat", s:5},{t:"Ikut gotong royong membantu warga yang terdampak banjir", s:4},{t:"Memberi sumbangan dana saja tanpa ikut ke lapangan", s:3},{t:"Tidak ikut karena evakuasi adalah tugas BPBD, bukan kecamatan", s:2},{t:"Memanfaatkan momen banjir untuk pencitraan foto lalu pergi", s:1}], ex:"Terjun dan mengoordinasikan bantuan saat bencana menunjukkan pengabdian tulus; menjadikan musibah warga sebagai ajang pencitraan adalah tidak berempati."},
{id:"TKP-2082", q:"Joko selalu ngotot ingin menjadi ketua dalam setiap kepanitiaan tim dan tersinggung bila tidak dipilih. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan sistem rotasi ketua panitia yang disepakati tim agar semua mendapat kesempatan memimpin dan belajar", s:5},{t:"Memberi kesempatan kepada anggota lain menjadi ketua secara bergantian", s:4},{t:"Selalu memilih Joko agar tidak ada keributan", s:3},{t:"Mendukung siapa pun asal bukan Joko untuk memberinya pelajaran", s:2},{t:"Menyebarkan bahwa Joko gila hormat dan haus jabatan", s:1}], ex:"Rotasi kepemimpinan yang disepakati memberi kesempatan adil sekaligus melatih semua anggota; menjelekkan ambisi rekan tidak menyelesaikan masalah."},
{id:"TKP-2083", q:"Rekan Anda yang beragama Buddha akan merayakan Waisak dan memohon izin tidak masuk untuk bersembahyang di wihara. Sikap yang paling tepat adalah ....", opts:[{t:"Mendukung pemberian izin dan membantu mengatur pengganti tugasnya selama ia beribadah", s:5},{t:"Menyetujui izinnya sebagai hak menjalankan ibadah", s:4},{t:"Menyerahkan keputusan sepenuhnya kepada atasan tanpa memberi pendapat", s:3},{t:"Menolak karena pekerjaan sedang banyak", s:2},{t:"Mengejek ritual di wihara sebagai penyembahan berhala", s:1}], ex:"Memfasilitasi ibadah rekan lintas agama adalah wujud nyata toleransi; merendahkan ritual kepercayaannya adalah penistaan yang merusak kerukunan."},
{id:"TKP-2084", q:"Libur nasional yang panjang membuat jadwal piket kantor harus diisi, tetapi tidak ada yang bersedia. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan penyusunan jadwal piket bergilir yang adil dengan kompensasi yang jelas, diputuskan melalui musyawarah tim", s:5},{t:"Bersedia mengisi salah satu jadwal piket tersebut", s:4},{t:"Menunggu ditunjuk atasan karena tidak ada yang mau sukarela", s:3},{t:"Berpura-pura sudah ada rencana keluarga agar tidak kebagian piket", s:2},{t:"Menghasut rekan lain agar kompak menolak piket libur nasional", s:1}], ex:"Skema piket bergilir yang adil hasil musyawarah menyeimbangkan kewajiban dan hak pegawai; berpura-pura berhalangan adalah ketidakjujuran."},
{id:"TKP-2085", q:"Dalam rapat, Heru mengkritik hasil kerja Anda dengan nada merendahkan di depan semua peserta. Sikap yang paling tepat adalah ....", opts:[{t:"Tetap tenang, menanggapi kritiknya secara objektif pada substansinya, dan mengajaknya berdiskusi lebih lanjut secara pribadi bila perlu", s:5},{t:"Menjawab kritiknya dengan tenang tanpa terpancing emosi", s:4},{t:"Diam dan menahan malu selama rapat berlangsung", s:3},{t:"Membalas mengkritik Heru dengan nada yang sama merendahkannya", s:2},{t:"Menunggu rapat selesai lalu menyebarkan keburukan Heru ke rekan lain", s:1}], ex:"Menanggapi kritik pada substansinya dengan tenang menunjukkan kedewasaan profesional; membalas merendahkan hanya menurunkan martabat diri sendiri."},
{id:"TKP-2086", q:"Seorang warga datang ke kantor membawa sesaji untuk ritual adat sebelum mengurus perizinan, padahal aturan melarang membawa barang sesajen ke area pelayanan. Sikap yang paling tepat adalah ....", opts:[{t:"Menjelaskan aturan dengan bahasa yang santun dan penuh hormat pada adatnya, serta mencarikan solusi seperti menitipkan sesaji di tempat yang layak", s:5},{t:"Meminta warga menyimpan sesajinya di luar area pelayanan dengan penjelasan yang baik", s:4},{t:"Menolak mentah-mentah dan menyuruh warga membuang sesajinya", s:3},{t:"Membiarkan saja karena tidak enak menegur warga yang sedang ritual", s:2},{t:"Mengejek ritual warga tersebut di depan antrean", s:1}], ex:"Menegakkan aturan dengan bahasa yang menghormati adat warga menyeimbangkan ketertiban dan kearifan lokal; mengejek ritualnya melukai martabat masyarakat."},
{id:"TKP-2087", q:"Tim Anda berhasil menyelesaikan program besar tepat waktu dan pimpinan memberi apresiasi. Sikap yang paling tepat dalam merayakannya adalah ....", opts:[{t:"Merayakan bersama seluruh tim termasuk staf pendukung, dengan mengakui kontribusi setiap orang secara terbuka", s:5},{t:"Mengadakan syukuran sederhana bersama seluruh anggota tim", s:4},{t:"Merayakan secukupnya tanpa perlu melibatkan semua orang", s:3},{t:"Hanya merayakan dengan anggota inti yang paling berperan", s:2},{t:"Mengklaim keberhasilan itu terutama berkat jasa Anda di depan pimpinan", s:1}], ex:"Merayakan keberhasilan dengan mengakui semua kontributor memperkuat soliditas tim; mengklaim jasa sepihak adalah kesombongan yang merusak kekompakan."},
{id:"TKP-2088", q:"Anak Sari sakit keras dan ia harus izin mendadak padahal hari itu ada pelayanan massal yang membutuhkan banyak petugas. Sikap yang paling tepat adalah ....", opts:[{t:"Segera mengatur ulang pembagian tugas dengan rekan lain untuk menutupi kekosongan Sari, sambil menyampaikan doa untuk kesembuhan anaknya", s:5},{t:"Menggantikan tugas Sari pada pelayanan massal tersebut", s:4},{t:"Melaporkan ketidakhadiran Sari ke atasan dan menunggu pengganti", s:3},{t:"Mengeluh karena ketidakhadiran Sari menambah beban Anda", s:2},{t:"Menuduh Sari mengada-ada agar bisa bolos dari tugas berat", s:1}], ex:"Sigap menutup kekosongan akibat musibah rekan dengan empati menunjukkan solidaritas; menuduhnya berbohong saat anaknya sakit adalah prasangka yang kejam."},
{id:"TKP-2089", q:"Rekan Anda terbiasa mengucapkan salam sesuai agamanya setiap bertemu, dan seorang rekan baru merasa tersinggung karena salam itu bukan dari agamanya. Sikap yang paling tepat adalah ....", opts:[{t:"Menjelaskan kepada rekan baru bahwa salam adalah doa kebaikan dalam tiap agama dan saling menghormati adalah budaya bangsa kita", s:5},{t:"Menenangkan rekan baru dan memintanya memaklumi kebiasaan tersebut", s:4},{t:"Tidak ikut campur karena itu urusan keyakinan masing-masing", s:3},{t:"Meminta rekan lama berhenti mengucapkan salamnya agar tidak menyinggung", s:2},{t:"Mendukung rekan baru memprotes keras kebiasaan tersebut", s:1}], ex:"Menjelaskan makna salam sebagai doa kebaikan menumbuhkan saling pengertian antarumat; melarang orang mengucap salam agamanya adalah intoleransi."},
{id:"TKP-2090", q:"Tim futsal antar unit akan dibentuk dan Anda diminta mengoordinasikannya. Beberapa pegawai enggan ikut karena merasa tidak bisa bermain. Sikap yang paling tepat adalah ....", opts:[{t:"Merancang kegiatan yang inklusif dengan peran non-pemain seperti suporter dan panitia, sehingga semua bisa berpartisipasi sesuai kemampuan", s:5},{t:"Mengajak yang enggan ikut sebagai pendukung tim", s:4},{t:"Membentuk tim hanya dari yang bisa bermain", s:3},{t:"Memaksa semua pegawai ikut bermain demi kekompakan", s:2},{t:"Membatalkan kegiatan karena peminatnya sedikit", s:1}], ex:"Merancang partisipasi inklusif sesuai kemampuan menumbuhkan kebersamaan tanpa paksaan; memaksa yang tidak bisa justru menimbulkan ketertekanan."},
{id:"TKP-2091", q:"Eko melakukan kesalahan input yang merugikan dan memohon Anda menutupinya dari atasan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menutupi kesalahannya, membantunya menyusun klarifikasi jujur kepada atasan, dan mencari solusi perbaikan bersama", s:5},{t:"Menolak menutupi dan menyarankan Eko mengaku sendiri kepada atasan", s:4},{t:"Menutupinya sekali ini karena Eko berjanji tidak mengulangi", s:3},{t:"Menutupinya dengan syarat Eko mengerjakan tugas Anda sebulan", s:2},{t:"Menutupinya lalu menggunakannya untuk mengancam Eko di kemudian hari", s:1}], ex:"Menolak menutupi sambil membantu klarifikasi jujur menegakkan integritas tanpa meninggalkan rekan; menutupi kesalahan adalah kebohongan yang merusak akuntabilitas."},
{id:"TKP-2092", q:"Hari Raya Galungan tiba dan Wayan, rekan Anda yang beragama Hindu, mengundang tim ke rumahnya untuk persembahyangan bersama keluarga. Sikap yang paling tepat adalah ....", opts:[{t:"Menghadiri undangan dengan penuh hormat dan mengikuti tata cara yang berlaku sebagai penghargaan pada hari sucinya", s:5},{t:"Menghadiri undangan Wayan sebagai bentuk dukungan", s:4},{t:"Mengucapkan selamat saja tanpa hadir karena berbeda keyakinan", s:3},{t:"Menolak hadir dengan alasan tidak paham ritual Hindu", s:2},{t:"Menganggap undangan itu upaya memengaruhi keyakinan Anda", s:1}], ex:"Menghadiri dan menghormati hari suci rekan lintas agama mempererat persaudaraan; mencurigainya sebagai upaya memengaruhi keyakinan adalah prasangka intoleran."},
{id:"TKP-2093", q:"Pak Slamet, pegawai senior yang akan pensiun, menyimpan banyak pengetahuan tentang arsip dan prosedur lama yang belum terdokumentasi. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan program alih pengetahuan di mana tim mendokumentasikan pengalaman Pak Slamet sebelum ia pensiun, sebagai penghormatan atas jasanya", s:5},{t:"Meminta Pak Slamet berbagi pengalamannya kepada tim sebelum pensiun", s:4},{t:"Membiarkannya pensiun dengan tenang tanpa merepotkannya", s:3},{t:"Menganggap pengetahuan lama sudah tidak relevan dengan sistem baru", s:2},{t:"Mendesaknya segera pensiun agar regenerasi berjalan cepat", s:1}], ex:"Mendokumentasikan pengetahuan senior sebelum pensiun menghormati jasanya sekaligus menjaga keberlanjutan tim; menganggapnya tidak relevan adalah kesombongan."},
{id:"TKP-2094", q:"Seorang anggota tim mengundurkan diri mendadak dan bebannya harus dibagi ke anggota yang tersisa hingga pengganti datang. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak tim yang tersisa bermusyawarah membagi beban secara adil dan sementara, sambil mengusulkan percepatan rekrutmen pengganti", s:5},{t:"Ikut memikul sebagian beban tambahan selama masa transisi", s:4},{t:"Menerima beban tambahan apa adanya tanpa banyak bertanya", s:3},{t:"Menolak beban tambahan karena bukan kesalahan Anda ia mengundurkan diri", s:2},{t:"Menjelekkan rekan yang mengundurkan diri sebagai tidak bertanggung jawab", s:1}], ex:"Musyawarah pembagian beban sementara yang adil menjaga kinerja tim di masa transisi; menolak membantu justru memperberat rekan yang tersisa."},
{id:"TKP-2095", q:"Rekan Anda yang baru melahirkan membutuhkan ruang privat untuk memerah ASI di kantor, tetapi belum ada fasilitasnya. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan kepada pimpinan penyediaan ruang laktasi dan pengaturan jadwal yang mendukung, sebagai bentuk kepedulian pada pegawai", s:5},{t:"Membantu mencarikan ruangan kosong yang bisa dipakai sementara", s:4},{t:"Menyarankan ia memerah ASI di rumah saja sebelum dan sesudah kerja", s:3},{t:"Menganggap itu masalah pribadinya bukan urusan kantor", s:2},{t:"Mengejeknya sebagai pegawai yang merepotkan", s:1}], ex:"Mengusulkan fasilitas pendukung bagi ibu menyusui menunjukkan kepedulian dan kesetaraan; menganggapnya masalah pribadi mengabaikan hak pegawai."},
{id:"TKP-2096", q:"Tim Anda sering ribut soal hal sepele karena tidak ada aturan main yang jelas. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan penyusunan kesepakatan kerja tim yang memuat pembagian peran, tata komunikasi, dan mekanisme penyelesaian konflik, disepakati bersama", s:5},{t:"Mengusulkan dibuatnya aturan main yang jelas bagi tim", s:4},{t:"Mengikuti arus saja selama tidak merugikan Anda", s:3},{t:"Memihak kelompok yang paling kuat agar posisi Anda aman", s:2},{t:"Memanfaatkan kekacauan untuk mengambil keuntungan pribadi", s:1}], ex:"Kesepakatan kerja yang disusun bersama memberi landasan jelas bagi kekompakan tim; memanfaatkan kekacauan untuk keuntungan pribadi adalah oportunisme."},
{id:"TKP-2097", q:"Rekan Anda yang beragama Kristen harus mengikuti ibadah Minggu pagi, padahal ia terjadwal piket Minggu. Ia meminta bertukar jadwal dengan Anda. Sikap yang paling tepat adalah ....", opts:[{t:"Menyetujui tukar jadwal dengan senang hati sebagai bentuk penghormatan pada ibadahnya, dan ia pun bersedia menggantikan Anda di lain waktu", s:5},{t:"Menyetujui permintaan tukar jadwalnya", s:4},{t:"Menolak karena jadwal piket sudah ditetapkan dan tidak bisa diubah", s:3},{t:"Menyetujui dengan syarat ia memberi imbalan", s:2},{t:"Melaporkannya sebagai pegawai yang mementingkan ibadah di atas tugas", s:1}], ex:"Saling bertukar jadwal demi ibadah mencerminkan toleransi dan gotong royong; menjadikan ibadah sebagai alasan laporan menunjukkan ketidakpekaan beragama."},
{id:"TKP-2098", q:"Anda mengetahui Rudi membocorkan strategi dan data internal tim ke unit lain yang menjadi pesaing program. Sikap yang paling tepat adalah ....", opts:[{t:"Berbicara tegas dengan Rudi agar menghentikan perbuatannya, dan bila berlanjut melaporkannya melalui jalur resmi demi kepentingan tim", s:5},{t:"Menegur Rudi agar tidak membocorkan data internal tim", s:4},{t:"Membiarkannya karena bukan data yang terlalu rahasia", s:3},{t:"Ikut membocorkan data tim ke pihak lain agar seimbang", s:2},{t:"Menyebarkan perbuatan Rudi ke seluruh kantor agar ia malu", s:1}], ex:"Menegur lalu menempuh jalur resmi bila berlanjut melindungi kepentingan tim secara beretika; ikut membocorkan atau mengumbar aibnya merusak kepercayaan."},
{id:"TKP-2099", q:"Kecamatan mengadakan festival budaya dan unit Anda diminta membuka stan mengenalkan program pelayanan. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak tim merancang stan yang interaktif dan melibatkan unsur budaya lokal agar masyarakat tertarik mengenal program pelayanan", s:5},{t:"Berpartisipasi aktif dalam menyiapkan stan bersama tim", s:4},{t:"Hadir sekadarnya karena festival bukan tugas pokok Anda", s:3},{t:"Menolak ditugaskan dengan alasan sibuk pekerjaan kantor", s:2},{t:"Menganggap festival budaya sebagai pemborosan anggaran", s:1}], ex:"Memanfaatkan festival budaya untuk mendekatkan pelayanan pada masyarakat menunjukkan kreativitas dan kepedulian; meremehkannya mengabaikan jembatan dengan warga."},
{id:"TKP-2100", q:"Dalam tim Anda, Budi bekerja lambat tetapi sangat teliti, sedangkan Andi bekerja cepat tetapi sering kurang cermat. Keduanya sering saling menyindir. Sikap yang paling tepat adalah ....", opts:[{t:"Membantu keduanya melihat bahwa ketelitian dan kecepatan saling melengkapi, lalu mengusulkan pembagian peran sesuai kelebihan masing-masing", s:5},{t:"Menasihati keduanya agar saling menghargai perbedaan gaya kerja", s:4},{t:"Tidak ikut campur karena itu dinamika biasa dalam tim", s:3},{t:"Mendukung Andi karena kecepatan lebih dibutuhkan tim", s:2},{t:"Mengadu domba keduanya agar salah satu tersingkir", s:1}], ex:"Memadukan kelebihan masing-masing gaya kerja mengubah perbedaan menjadi kekuatan tim; mengadu domba menghancurkan potensi kolaborasi."},{id:"TKP-2101", q:"Dalam rapat, Sari mengusulkan ide perbaikan pelayanan yang berbeda dari kebiasaan unit Anda. Sebagian rekan langsung mencibirnya. Sikap yang paling tepat adalah ....", opts:[{t:"Membela Sari dengan meminta forum memberi kesempatan menjelaskan idenya sampai tuntas, karena ide baru layak diuji bukan dicibir", s:5},{t:"Mendukung Sari agar idenya dipertimbangkan secara serius", s:4},{t:"Diam saja karena tidak ingin berseberangan dengan mayoritas", s:3},{t:"Ikut mencibir agar tidak dianggap aneh oleh rekan lain", s:2},{t:"Menyarankan Sari berhenti mengusulkan ide agar tidak dicibir lagi", s:1}], ex:"Memberi ruang bagi ide baru untuk dijelaskan menunjukkan keterbukaan dan penghargaan; ikut mencibir membunuh kreativitas tim."},
{id:"TKP-2102", q:"Rekan Anda yang beretnis Tionghoa mengajukan cuti saat Imlek untuk berkumpul dengan keluarga besarnya. Beban kerjanya harus ditanggung tim selama ia cuti. Sikap yang paling tepat adalah ....", opts:[{t:"Mendukung cutinya sebagai hak merayakan hari besar keagamaannya dan bersama tim mengatur ulang pembagian tugas selama ia tidak ada", s:5},{t:"Menyetujui cutinya dan ikut menutupi pekerjaannya", s:4},{t:"Menyerahkan keputusan cuti sepenuhnya kepada atasan", s:3},{t:"Keberatan karena cutinya menambah beban tim", s:2},{t:"Menyindir bahwa Imlek bukan hari besar yang perlu dirayakan serius", s:1}], ex:"Menghormati hak cuti hari besar keagamaan setiap pegawai adalah toleransi; merendahkan hari rayanya mencederai kerukunan."},
{id:"TKP-2103", q:"Dua tim di unit Anda berebut memakai ruang rapat yang sama pada jam yang sama untuk kegiatan penting. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan musyawarah cepat untuk berbagi waktu atau mencari ruang alternatif, dengan prioritas pada kegiatan yang paling mendesak", s:5},{t:"Mengajak tim lain bernegosiasi pembagian waktu pemakaian ruangan", s:4},{t:"Mengalah dan mencari ruang lain meski kurang representatif", s:3},{t:"Bersikeras memakai ruangan karena tim Anda memesan lebih dulu", s:2},{t:"Menyebarkan bahwa tim lain tidak tahu aturan pemakaian ruangan", s:1}], ex:"Musyawarah pembagian ruang dengan prioritas yang jelas menyelesaikan rebutan secara adil; bersikukuh tanpa dialog menimbulkan permusuhan antar tim."},
{id:"TKP-2104", q:"Seorang rekan melontarkan stereotip negatif tentang suku asal Yosua setiap kali ia melakukan kesalahan kecil. Yosua terlihat tertekan. Sikap yang paling tepat adalah ....", opts:[{t:"Menegur pelaku dengan tegas bahwa kesalahan individu tidak boleh dikaitkan dengan sukunya, serta memberi dukungan moral kepada Yosua", s:5},{t:"Menasihati pelaku agar berhenti mengaitkan kesalahan dengan suku", s:4},{t:"Menghibur Yosua secara pribadi tanpa menegur pelaku", s:3},{t:"Menganggapnya candaan biasa yang tidak perlu dibesar-besarkan", s:2},{t:"Ikut menambahkan stereotip agar terlihat akrab dengan pelaku", s:1}], ex:"Menegur stereotip suku dan membela korban menegakkan martabat dan persatuan; mengaitkan kesalahan individu dengan suku adalah rasisme."},
{id:"TKP-2105", q:"Bencana longsor terjadi di wilayah kerja Anda dan tim tanggap darurat dibentuk mendadak dari beberapa unit. Koordinasi masih kacau. Sikap yang paling tepat adalah ....", opts:[{t:"Mengambil inisiatif menyusun pembagian peran yang jelas dan jalur komunikasi cepat agar bantuan segera sampai ke warga", s:5},{t:"Aktif membantu sesuai kemampuan sambil mengikuti arahan koordinator", s:4},{t:"Menunggu perintah atasan sebelum bergerak", s:3},{t:"Hanya membantu bila diminta karena bukan unit tugas Anda", s:2},{t:"Memanfaatkan situasi untuk mencari muka di depan pimpinan", s:1}], ex:"Inisiatif menata koordinasi dalam kedaruratan menyelamatkan nyawa warga; menunggu perintah sambil berpangku tangan mengabaikan panggilan kemanusiaan."},
{id:"TKP-2106", q:"Rekan Anda mengajak bermain judi online bersama dengan iming-iming keuntungan cepat di sela jam kerja. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas, mengingatkan bahwa judi melanggar hukum dan etika ASN, serta menyarankannya menjauhi ajakan tersebut", s:5},{t:"Menolak ajakan tersebut karena tidak tertarik", s:4},{t:"Mendengarkan penjelasannya tetapi tidak ikut bermain", s:3},{t:"Ikut mencoba sekali dengan modal kecil", s:2},{t:"Ikut bermain lalu mengajak rekan lain agar semakin ramai", s:1}], ex:"Menolak judi sekaligus mengingatkan bahayanya menegakkan integritas ASN; ikut bermain berarti melanggar hukum dan merusak martabat aparatur."},
{id:"TKP-2107", q:"Upacara bendera di kantor Anda rutin diawali doa. Muncul usul agar doa dipimpin bergantian oleh perwakilan tiap agama yang ada. Sikap yang paling tepat adalah ....", opts:[{t:"Mendukung usul doa bergilir sebagai wujud nyata penghormatan pada keberagaman keyakinan seluruh pegawai", s:5},{t:"Setuju dengan usul tersebut demi kerukunan bersama", s:4},{t:"Tidak berpendapat dan mengikuti keputusan panitia upacara", s:3},{t:"Menolak karena doa sebaiknya mengikuti agama mayoritas", s:2},{t:"Memprotes usul tersebut sebagai upaya mencampuradukkan agama", s:1}], ex:"Doa bergilir antarumat beragama dalam upacara resmi mencerminkan persatuan dalam keberagaman; memaksakan satu agama mengingkari semangat toleransi."},
{id:"TKP-2108", q:"Fajar memprotes hasil rapat padahal ia tidak hadir dan tidak membaca notulen yang sudah dibagikan. Sikap yang paling tepat adalah ....", opts:[{t:"Menjelaskan dengan sabar isi keputusan rapat dan memintanya membaca notulen terlebih dahulu sebelum menyampaikan keberatan resmi", s:5},{t:"Memintanya membaca notulen rapat sebelum protes", s:4},{t:"Membiarkannya protes karena itu haknya sebagai anggota tim", s:3},{t:"Mendukung protesnya agar keputusan rapat dibatalkan", s:2},{t:"Mengejeknya sebagai anggota tim yang tidak pernah hadir tapi banyak protes", s:1}], ex:"Mengarahkan rekan pada informasi yang benar sebelum protes menjaga tertib musyawarah; mengejeknya hanya menambah konflik tanpa solusi."},
{id:"TKP-2109", q:"Rekan Anda yang bersuku Dayak akan mengikuti upacara adat keluarganya dan meminta izin beberapa hari. Sebagian rekan menganggapnya berlebihan. Sikap yang paling tepat adalah ....", opts:[{t:"Mendukung izinnya sebagai hak menjalankan adat istiadat dan membantu menutupi tugasnya selama ia berhalangan", s:5},{t:"Menyetujui izinnya dan memaklumi keperluannya", s:4},{t:"Menyerahkan keputusan izin kepada atasan", s:3},{t:"Ikut menganggap izin adatnya berlebihan", s:2},{t:"Menyebarkan bahwa ia memakai adat sebagai alasan untuk bermalas-malasan", s:1}], ex:"Menghormati hak menjalankan upacara adat dan membantu menutupi tugasnya adalah toleransi budaya; mencurigai adatnya sebagai alasan malas adalah prasangka."},
{id:"TKP-2110", q:"Tim Anda ditugaskan mempresentasikan capaian program di depan bupati. Masih bingung siapa memaparkan bagian apa. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan pembagian peran presentasi sesuai penguasaan materi masing-masing dan latihan bersama agar tampil kompak", s:5},{t:"Menawarkan diri memaparkan bagian yang paling Anda kuasai", s:4},{t:"Menunggu ketua tim membagi peran", s:3},{t:"Berebut bagian yang paling mudah dan bergengsi", s:2},{t:"Menolak tampil dengan alasan demam panggung", s:1}], ex:"Pembagian peran sesuai penguasaan materi plus latihan bersama menghasilkan presentasi tim yang solid; berebut bagian bergengsi menunjukkan egoisme."},
{id:"TKP-2111", q:"Rekan Anda meminta tolong dikerjakan tugas pribadinya, seperti mengurus administrasi keluarganya, pada jam kerja. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan halus karena jam kerja adalah amanah negara, sambil menawarkan membantu di luar jam kerja bila memungkinkan", s:5},{t:"Menolak karena Anda juga sibuk dengan pekerjaan sendiri", s:4},{t:"Membantunya sebentar karena hanya tugas kecil", s:3},{t:"Menerima dengan syarat ia membantu tugas Anda sebagai imbalan", s:2},{t:"Menerima lalu melaporkannya ke atasan agar ia terkena sanksi", s:1}], ex:"Menolak tugas pribadi di jam kerja dengan tetap menawarkan bantuan di luar jam dinas menjaga amanah sekaligus empati; menerimanya berarti menyalahgunakan waktu negara."},
{id:"TKP-2112", q:"Rekan Anda yang bersuku Batak mengundang tim ke pesta adat pernikahannya yang meriah dengan tortor dan ulos. Sikap yang paling tepat adalah ....", opts:[{t:"Menghadiri dengan antusias dan menghormati seluruh rangkaian adatnya sebagai bentuk penghargaan pada budaya Batak", s:5},{t:"Menghadiri undangannya sebagai dukungan kepada rekan", s:4},{t:"Memberi ucapan selamat tanpa hadir karena acaranya jauh", s:3},{t:"Menolak hadir karena tidak terbiasa dengan adat Batak", s:2},{t:"Mengolok-olok pakaian adat ulos sebagai kain gorden", s:1}], ex:"Menghadiri dan menghargai pesta adat rekan mempererat persaudaraan lintas suku; mengolok pakaian adatnya adalah penghinaan budaya."},
{id:"TKP-2113", q:"Program tim gagal mencapai target dan seorang rekan menuding Anda sebagai penyebab utama di depan atasan. Sikap yang paling tepat adalah ....", opts:[{t:"Menanggapi dengan tenang, memaparkan fakta kontribusi masing-masing secara objektif, dan mengajak evaluasi bersama tanpa saling tuding", s:5},{t:"Membela diri dengan menjelaskan fakta yang sebenarnya", s:4},{t:"Diam menerima tudingan agar tidak memperpanjang masalah", s:3},{t:"Balik menuding rekan tersebut sebagai penyebab kegagalan", s:2},{t:"Menyebarkan keburukan rekan tersebut ke seluruh kantor sebagai balasan", s:1}], ex:"Menjawab tudingan dengan fakta dan mengajak evaluasi objektif menunjukkan kedewasaan; balik menuding atau menyebar fitnah hanya memperkeruh konflik."},
{id:"TKP-2114", q:"Tim Anda menerima anggota baru yang tunanetra. Ia kesulitan membaca dokumen cetak yang menjadi bahan kerja tim. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan agar dokumen penting disediakan dalam format digital yang bisa dibaca pembaca layar, sehingga ia bekerja setara dengan anggota lain", s:5},{t:"Membantu membacakan dokumen penting saat ia membutuhkan", s:4},{t:"Membiarkannya meminta bantuan sendiri bila kesulitan", s:3},{t:"Tidak melibatkannya dalam pekerjaan yang membutuhkan banyak membaca", s:2},{t:"Mengusulkan ia dipindahkan ke unit yang tidak banyak dokumen", s:1}], ex:"Menyediakan dokumen aksesibel memastikan kesetaraan kesempatan bagi penyandang disabilitas; menyingkirkannya dari pekerjaan adalah diskriminasi."},
{id:"TKP-2115", q:"Keluarga rekan Anda yang berbeda agama sedang berduka. Tim berencana takziah bersama. Sikap yang paling tepat adalah ....", opts:[{t:"Ikut takziah dengan menghormati tata cara duka sesuai agamanya, sebagai wujud empati kemanusiaan tanpa memandang perbedaan keyakinan", s:5},{t:"Ikut takziah bersama tim sebagai bentuk belasungkawa", s:4},{t:"Mengirim karangan bunga tanpa ikut hadir", s:3},{t:"Tidak ikut karena tata cara dukanya berbeda dengan keyakinan Anda", s:2},{t:"Melarang tim takziah karena berbeda agama", s:1}], ex:"Takziah lintas agama dengan menghormati tata caranya adalah empati kemanusiaan yang melampaui sekat keyakinan; melarangnya adalah intoleransi."},
{id:"TKP-2116", q:"Ketua tim Anda selalu memutuskan sendiri tanpa pernah meminta pendapat anggota, dan banyak keputusan yang kurang tepat. Sikap yang paling tepat adalah ....", opts:[{t:"Menyampaikan secara santun dalam forum tim agar keputusan penting dibahas bersama demi kualitas yang lebih baik", s:5},{t:"Menyarankan ketua untuk lebih sering berdiskusi dengan anggota", s:4},{t:"Mengikuti semua keputusannya karena ia ketua tim", s:3},{t:"Melawan setiap keputusannya secara terbuka", s:2},{t:"Menghasut anggota lain untuk menjatuhkan ketua tim", s:1}], ex:"Mengusulkan pengambilan keputusan partisipatif melalui forum yang santun memperbaiki kualitas tanpa merusak hierarki; menghasut menjatuhkan pimpinan adalah pengkhianatan."},
{id:"TKP-2117", q:"Rekan Anda yang bersuku Minang mengajukan cuti panjang saat Lebaran untuk pulang kampung yang jauh, sementara tim kekurangan personel. Sikap yang paling tepat adalah ....", opts:[{t:"Mendukung haknya pulang kampung dan bersama tim menyusun jadwal pengganti yang adil selama ia cuti", s:5},{t:"Menyetujui cutinya dan ikut menutupi tugasnya", s:4},{t:"Menyerahkan keputusan kepada atasan tanpa memberi masukan", s:3},{t:"Keberatan karena cutinya merepotkan tim", s:2},{t:"Menuduhnya Lebaran hanya alasan untuk liburan panjang", s:1}], ex:"Menghormati tradisi pulang kampung sekaligus menata pengganti secara adil menyeimbangkan hak individu dan kebutuhan tim; menuduhnya berbohong adalah prasangka buruk."},
{id:"TKP-2118", q:"Tim Anda belum memiliki pedoman kerja yang jelas sehingga sering terjadi tumpang tindih tugas. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan penyusunan SOP tim secara partisipatif agar peran tiap anggota jelas dan tumpang tindih terhindarkan", s:5},{t:"Mengusulkan dibuatnya pembagian tugas tertulis", s:4},{t:"Bekerja sesuai kebiasaan masing-masing seperti selama ini", s:3},{t:"Mengambil alih tugas rekan yang tumpang tindih dengan tugas Anda", s:2},{t:"Memanfaatkan ketidakjelasan untuk menghindari tugas yang berat", s:1}], ex:"SOP yang disusun partisipatif memberi kejelasan peran dan mencegah konflik; memanfaatkan kekacauan untuk menghindari tugas adalah kemalasan yang terselubung."},
{id:"TKP-2119", q:"Di jam kerja, beberapa rekan mengajak Anda nongkrong di kantin dengan alasan suntuk. Pekerjaan Anda belum selesai. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan halus dan menyelesaikan pekerjaan terlebih dahulu, lalu bergabung bila masih sempat di jam istirahat", s:5},{t:"Menolak ajakan tersebut karena pekerjaan belum selesai", s:4},{t:"Ikut sebentar lalu kembali bekerja", s:3},{t:"Ikut nongkrong karena tidak enak menolak ajakan rekan", s:2},{t:"Ikut nongkrong sambil mengajak rekan lain meninggalkan pekerjaannya", s:1}], ex:"Menyelesaikan amanah sebelum bersantai menunjukkan disiplin dan tanggung jawab; mengajak rekan lain ikut meninggalkan pekerjaan merusak etos kerja tim."},
{id:"TKP-2120", q:"Rekan Anda yang beragama Hindu meminta izin menghadiri upacara odalan di pura keluarganya di Bali. Sikap yang paling tepat adalah ....", opts:[{t:"Mendukung izinnya sebagai kewajiban adat dan agama, serta membantu mengatur pengganti tugasnya", s:5},{t:"Menyetujui izinnya dan memaklumi keperluannya", s:4},{t:"Menyerahkan sepenuhnya kepada kebijakan atasan", s:3},{t:"Keberatan karena lokasinya jauh dan cutinya lama", s:2},{t:"Mengejek upacara odalan sebagai ritual yang tidak penting", s:1}], ex:"Menghormati kewajiban adat-agama rekan dengan membantu pengaturan pengganti adalah toleransi yang konkret; merendahkan ritualnya melukai kerukunan beragama."},
{id:"TKP-2121", q:"Seorang pegawai baru pindahan dari luar daerah tampak canggung dan belum punya teman di kantor Anda. Sikap yang paling tepat adalah ....", opts:[{t:"Aktif menyapanya, mengenalkannya pada tim, dan membantunya beradaptasi dengan lingkungan serta budaya kerja setempat", s:5},{t:"Menyapanya dan menawarkan bantuan bila ia membutuhkan", s:4},{t:"Membiarkannya beradaptasi sendiri seperti pegawai baru pada umumnya", s:3},{t:"Mengabaikannya karena bukan tanggung jawab Anda", s:2},{t:"Memanfaatkan kecanggungannya untuk menyuruhnya mengerjakan tugas-tugas Anda", s:1}], ex:"Aktif membantu rekan baru beradaptasi mempercepat integrasinya ke dalam tim; memanfaatkannya untuk kepentingan pribadi adalah perundungan."},
{id:"TKP-2122", q:"Demi mencapai target tim, seorang rekan mengusulkan memanipulasi sedikit angka capaian dalam laporan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas dan mengingatkan bahwa target harus dicapai dengan cara jujur, serta mengajak tim bekerja lebih keras secara benar", s:5},{t:"Menolak usulan manipulasi data tersebut", s:4},{t:"Tidak berkomentar dan membiarkan tim memutuskan", s:3},{t:"Setuju karena hanya sedikit dan demi nama baik tim", s:2},{t:"Setuju lalu melaporkan rekan tersebut agar Anda terlihat bersih", s:1}], ex:"Menolak manipulasi data sekaligus mengajak kerja keras yang jujur menegakkan integritas; menyetujui kebohongan demi target menghancurkan akuntabilitas."},
{id:"TKP-2123", q:"Keluarga rekan Anda yang bersuku Jawa mengadakan selamatan dan mengundang seluruh tim. Sikap yang paling tepat adalah ....", opts:[{t:"Menghadiri selamatan dengan menghormati tata caranya sebagai bentuk penghargaan pada tradisi Jawa", s:5},{t:"Menghadiri undangan selamatan tersebut", s:4},{t:"Memberi ucapan selamat tanpa hadir", s:3},{t:"Menolak hadir karena tidak memahami makna selamatan", s:2},{t:"Menganggap selamatan sebagai pemborosan yang tidak perlu", s:1}], ex:"Menghadiri dan menghormati tradisi selamatan rekan menunjukkan penghargaan pada budaya Jawa; meremehkannya sebagai pemborosan adalah ketidakpekaan budaya."},
{id:"TKP-2124", q:"Rapat tim mengalami kebuntuan karena dua pendapat sama-sama kuat dan tidak ada yang mau mengalah. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan jeda sejenak lalu memfasilitasi diskusi mencari jalan tengah yang mengakomodasi kepentingan kedua belah pihak", s:5},{t:"Mengusulkan voting untuk menentukan pendapat yang menang", s:4},{t:"Diam menunggu hingga ada yang mengalah sendiri", s:3},{t:"Mendukung salah satu pihak agar cepat selesai", s:2},{t:"Meninggalkan rapat karena dianggap buang-buang waktu", s:1}], ex:"Memfasilitasi jalan tengah setelah jeda menenangkan menunjukkan kepemimpinan musyawarah; kabur dari rapat adalah pelarian dari tanggung jawab."},
{id:"TKP-2125", q:"Rekan Anda yang bersuku Sunda mengundang tim ke acara khitanan putranya. Sikap yang paling tepat adalah ....", opts:[{t:"Menghadiri undangan dengan penuh sukacita sebagai bentuk kebersamaan dan penghargaan pada momen bahagia keluarganya", s:5},{t:"Menghadiri undangan khitanan tersebut", s:4},{t:"Memberi amplop dan ucapan selamat tanpa hadir", s:3},{t:"Menolak hadir karena khitanan adalah acara keluarga inti", s:2},{t:"Berkomentar bahwa acara khitanan tidak perlu dirayakan besar-besaran", s:1}], ex:"Menghadiri momen bahagia rekan lintas suku mempererat kekeluargaan tim; meremehkan perayaannya menunjukkan ketidakpedulian."},
{id:"TKP-2126", q:"Laporan harus diselesaikan malam ini dan hanya tersisa Anda dan Wulan di kantor. Wulan terlihat kelelahan dan ingin menyerah. Sikap yang paling tepat adalah ....", opts:[{t:"Menyemangati Wulan, membagi sisa pekerjaan secara adil, dan menemaninya hingga selesai agar tidak ada yang berjuang sendirian", s:5},{t:"Membantu Wulan menyelesaikan bagiannya", s:4},{t:"Menyelesaikan bagian Anda sendiri lalu pulang", s:3},{t:"Menyuruh Wulan bertahan sendiri karena itu bagiannya", s:2},{t:"Meninggalkan Wulan sendirian dengan alasan Anda sudah lelah", s:1}], ex:"Saling menyemangati dan berbagi beban hingga tuntas adalah solidaritas tim sejati; meninggalkan rekan yang kelelahan sendirian mengkhianati kebersamaan."},
{id:"TKP-2127", q:"Anda ditugaskan ke daerah yang menerapkan aturan syariat dalam kehidupan publiknya. Sikap yang paling tepat selama bertugas di sana adalah ....", opts:[{t:"Mempelajari dan menghormati aturan setempat dengan menyesuaikan perilaku selama bertugas, sebagai penghargaan pada norma masyarakat", s:5},{t:"Mengikuti aturan setempat selama berada di daerah tersebut", s:4},{t:"Bersikap seperti biasa karena Anda hanya bertugas sementara", s:3},{t:"Terang-terangan melanggar aturan setempat sebagai bentuk protes", s:2},{t:"Mengejek aturan syariat tersebut di depan warga setempat", s:1}], ex:"Menghormati norma daerah penugasan menunjukkan adaptabilitas dan penghargaan pada kearifan lokal; menentangnya secara terbuka merusak hubungan dengan masyarakat."},
{id:"TKP-2128", q:"Seorang rekan mengajak Anda bekerja sama memenangkan tender untuk keluarganya dengan imbalan bagi hasil. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas dan mengingatkan bahwa kolusi tender melanggar hukum serta merusak kepercayaan publik pada instansi", s:5},{t:"Menolak ajakan tersebut karena berisiko hukum", s:4},{t:"Tidak menanggapi dan menjauhi rekan tersebut", s:3},{t:"Mempertimbangkannya karena imbalannya besar", s:2},{t:"Menerima tawaran tersebut lalu memeras rekan agar bagi hasilnya lebih besar", s:1}], ex:"Menolak kolusi sekaligus mengingatkan konsekuensinya menegakkan integritas; menerima tawaran berarti terlibat korupsi yang menghancurkan amanah publik."},
{id:"TKP-2129", q:"Rekan Anda yang bersuku Bugis akan menikah dengan adat Bugis-Makassar yang megah dan mengundang tim. Sikap yang paling tepat adalah ....", opts:[{t:"Menghadiri dan menghormati prosesi adatnya, bahkan menawarkan bantuan tenaga bila diperlukan, sebagai wujud persaudaraan", s:5},{t:"Menghadiri undangan pernikahannya", s:4},{t:"Mengirim kado tanpa hadir karena lokasi jauh", s:3},{t:"Tidak hadir tanpa kabar yang jelas", s:2},{t:"Mengomentari mahar adat Bugis sebagai memberatkan", s:1}], ex:"Menghadiri dan menghormati adat pernikahan Bugis-Makassar menunjukkan penghargaan pada budaya rekan; mengomentari maharnya adalah ketidaksopanan."},
{id:"TKP-2130", q:"Tim Anda diminta mengevaluasi program yang baru selesai. Seorang rekan menyampaikan kritik tajam terhadap bagian yang Anda kerjakan. Sikap yang paling tepat adalah ....", opts:[{t:"Menerima kritik dengan terbuka, mendiskusikan fakta-faktanya, dan menjadikannya bahan perbaikan program berikutnya", s:5},{t:"Mendengarkan kritiknya dan mempertimbangkan yang benar", s:4},{t:"Diam saja meski tidak setuju dengan kritiknya", s:3},{t:"Membalas mengkritik balik bagian yang dikerjakan rekan tersebut", s:2},{t:"Menuduhnya sengaja menjatuhkan Anda di depan tim", s:1}], ex:"Menerima kritik secara terbuka dan menjadikannya perbaikan menunjukkan kedewasaan profesional; menuduhnya berniat jahat menutup ruang evaluasi yang sehat."},
{id:"TKP-2131", q:"Rekan Anda meminta Anda mengabsenkannya pada apel pagi karena ia terlambat bangun. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas namun santun dan menyarankan ia segera berangkat serta mengajukan izin resmi bila memang berhalangan", s:5},{t:"Menolak karena tidak ingin terlibat kecurangan absensi", s:4},{t:"Mengabsenkannya sekali ini karena kasihan", s:3},{t:"Mengabsenkannya dengan imbalan traktiran", s:2},{t:"Mengabsenkannya lalu mengancam akan melaporkannya bila ia tidak menuruti Anda", s:1}], ex:"Menolak titip absen dengan memberi jalan keluar yang benar menjunjung kejujuran; mengabsenkannya berarti ikut memalsukan kehadiran."},
{id:"TKP-2132", q:"Rekan Anda yang berasal dari NTT akan melangsungkan pernikahan dengan adat belis yang melibatkan keluarga besar. Ia mengundang tim. Sikap yang paling tepat adalah ....", opts:[{t:"Menghadiri undangan dengan menghormati adat belis sebagai kekayaan budaya yang patut dihargai", s:5},{t:"Menghadiri undangannya sebagai bentuk dukungan", s:4},{t:"Mengucapkan selamat melalui pesan singkat", s:3},{t:"Menolak hadir karena tidak mengenal adat NTT", s:2},{t:"Menganggap adat belis sebagai praktik jual beli manusia", s:1}], ex:"Menghormati adat belis sebagai warisan budaya menunjukkan penghargaan pada keberagaman; menilainya dengan prasangka adalah ketidaktahuan yang menyakitkan."},
{id:"TKP-2133", q:"Menjelang deadline, hanya Anda dan Dedi yang masih lembur di kantor menyelesaikan laporan. Dedi mulai putus asa melihat tumpukan data. Sikap yang paling tepat adalah ....", opts:[{t:"Menyemangati Dedi, menyusun strategi menyelesaikan sisa data bersama, dan memastikan kalian pulang setelah semua beres", s:5},{t:"Membantu Dedi mengerjakan tumpukan datanya", s:4},{t:"Fokus menyelesaikan bagian Anda sendiri", s:3},{t:"Menyuruh Dedi bekerja lebih cepat agar tidak menghambat Anda", s:2},{t:"Pulang duluan dengan alasan kelelahan dan membiarkan Dedi sendiri", s:1}], ex:"Berjuang bersama hingga tuntas dengan strategi yang jelas adalah solidaritas tim; pulang meninggalkan rekan sendirian mengkhianati kebersamaan."},
{id:"TKP-2134", q:"Di daerah tugas Anda, masyarakat masih kuat memegang tradisi pela gandong yang mengikat persaudaraan antar desa. Sikap yang paling tepat dalam menjalankan program adalah ....", opts:[{t:"Memanfaatkan semangat pela gandong sebagai modal sosial untuk menggerakkan partisipasi warga dalam program", s:5},{t:"Menghormati tradisi tersebut dalam berinteraksi dengan warga", s:4},{t:"Mengabaikannya karena program sudah dirancang dari pusat", s:3},{t:"Menganggap tradisi itu menghambat modernisasi program", s:2},{t:"Melarang warga membawa-bawa tradisi dalam urusan program", s:1}], ex:"Menjadikan kearifan lokal sebagai modal sosial memperkuat penerimaan program; melarangnya justru memutus jembatan kepercayaan dengan masyarakat."},
{id:"TKP-2135", q:"Tim Anda berbeda pendapat soal alokasi anggaran kegiatan: sebagian ingin untuk pelatihan, sebagian untuk pengadaan sarana. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan pembahasan berbasis prioritas kebutuhan dengan data, lalu diputuskan melalui musyawarah yang transparan", s:5},{t:"Mengusulkan anggaran dibagi proporsional untuk keduanya", s:4},{t:"Mengikuti pendapat mayoritas tanpa banyak bertanya", s:3},{t:"Bersikeras pada pilihan Anda karena paling paham kebutuhan", s:2},{t:"Menyebarkan isu bahwa pihak lawan ingin mengorupsi anggaran", s:1}], ex:"Pembahasan berbasis data dan musyawarah transparan menghasilkan alokasi yang akuntabel; menyebar fitnah korupsi tanpa bukti adalah kejahatan."},
{id:"TKP-2136", q:"Rekan Anda yang bersuku Sasak mengajak tim menyaksikan festival Bau Nyale di daerahnya. Sikap yang paling tepat adalah ....", opts:[{t:"Ikut serta dengan antusias dan menghargai festival tersebut sebagai warisan budaya yang unik", s:5},{t:"Ikut menyaksikan festival Bau Nyale tersebut", s:4},{t:"Menolak dengan halus karena tidak tertarik", s:3},{t:"Menganggap festival itu sekadar keramaian tanpa makna", s:2},{t:"Mengejek kepercayaan di balik festival Bau Nyale", s:1}], ex:"Mengapresiasi festival budaya daerah rekan menumbuhkan kebanggaan pada keberagaman; mengejek kepercayaannya adalah penghinaan."},
{id:"TKP-2137", q:"Anda mendengar Sinta menyebarkan gosip tentang perceraian seorang rekan ke grup arisan kantor. Sikap yang paling tepat adalah ....", opts:[{t:"Menegur Sinta secara pribadi bahwa menyebarkan aib rumah tangga orang lain adalah perbuatan tercela dan memintanya berhenti", s:5},{t:"Menasihati Sinta agar tidak menyebarkan urusan pribadi orang lain", s:4},{t:"Mengabaikannya karena bukan urusan Anda", s:3},{t:"Ikut menyimak gosipnya karena penasaran", s:2},{t:"Menyebarkan gosip tersebut lebih luas agar semakin heboh", s:1}], ex:"Menegur penyebar gosip aib rumah tangga melindungi martabat rekan; ikut menyebarkannya berarti ikut menzalimi sesama."},
{id:"TKP-2138", q:"Rekan Anda yang bersuku Toraja harus pulang kampung untuk upacara Rambu Solo keluarganya yang berlangsung beberapa hari. Sikap yang paling tepat adalah ....", opts:[{t:"Mendukung kepergiannya sebagai kewajiban adat yang sakral dan membantu mengatur pengganti tugasnya", s:5},{t:"Menyetujui kepergiannya dan memaklumi", s:4},{t:"Menyerahkan keputusan izin kepada atasan", s:3},{t:"Keberatan karena upacaranya terlalu lama", s:2},{t:"Menganggap Rambu Solo sebagai pemborosan yang tidak masuk akal", s:1}], ex:"Menghormati kewajiban adat duka yang sakral dengan membantu pengaturan pengganti adalah empati budaya; meremehkannya melukai perasaan rekan yang berduka."},
{id:"TKP-2139", q:"Tim Anda harus menyusun laporan tahunan yang tebal dalam waktu dua minggu. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan pembagian bab sesuai keahlian, jadwal pengumpulan bertahap, dan review silang agar kualitas terjaga", s:5},{t:"Ikut mengambil bagian penyusunan sesuai pembagian tim", s:4},{t:"Menunggu pembagian tugas dari ketua tim", s:3},{t:"Mengambil bab yang paling tipis agar cepat selesai", s:2},{t:"Menyalin laporan tahun lalu dan mengganti angkanya saja", s:1}], ex:"Pembagian berbasis keahlian dengan review silang menjamin kualitas laporan tim; menyalin laporan lama adalah pemalsuan yang melanggar integritas."},
{id:"TKP-2140", q:"Menjelang diklat, seorang rekan menawarkan bocoran soal ujian dengan imbalan tertentu. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas dan mengingatkan bahwa kecurangan merusak integritas, serta mengajaknya belajar bersama dengan jujur", s:5},{t:"Menolak tawaran bocoran soal tersebut", s:4},{t:"Mengabaikan tawarannya tanpa menanggapi", s:3},{t:"Menerima bocorannya karena ingin lulus dengan nilai bagus", s:2},{t:"Menerima lalu menjual bocoran itu ke peserta diklat lain", s:1}], ex:"Menolak bocoran soal sekaligus mengajak belajar jujur menegakkan integritas ASN; menerimanya berarti mengkhianati prinsip kejujuran."},
{id:"TKP-2141", q:"Rekan Anda yang bersuku Madura mengajak tim menonton karapan sapi di daerahnya saat festival. Sikap yang paling tepat adalah ....", opts:[{t:"Ikut serta dan mengapresiasi karapan sapi sebagai kebanggaan budaya Madura yang mendunia", s:5},{t:"Ikut menonton festival karapan sapi tersebut", s:4},{t:"Menolak dengan halus karena tidak suka keramaian", s:3},{t:"Menganggap karapan sapi menyiksa hewan dan memprotesnya", s:2},{t:"Mengejek tradisi Madura sebagai kampungan", s:1}], ex:"Mengapresiasi kebanggaan budaya daerah rekan mempererat persaudaraan; mengejeknya sebagai kampungan adalah penghinaan suku."},
{id:"TKP-2142", q:"Dalam grup diskusi tim, Nita selalu pasif tidak pernah memberi tanggapan padahal pendapatnya dibutuhkan. Sikap yang paling tepat adalah ....", opts:[{t:"Menghubunginya secara pribadi, menanyakan kendalanya, dan mendorongnya berani menyampaikan pendapat dalam diskusi", s:5},{t:"Meminta Nita menyampaikan pendapatnya dalam diskusi", s:4},{t:"Membiarkannya karena mungkin ia memang tidak punya pendapat", s:3},{t:"Mengkritik kepasifannya di depan anggota grup", s:2},{t:"Mengeluarkannya dari grup diskusi karena dianggap tidak berkontribusi", s:1}], ex:"Menggali kendala secara pribadi dan mendorong keberanian berpendapat mengembangkan potensi rekan; mengeluarkannya dari grup adalah pengucilan."},
{id:"TKP-2143", q:"Pada HUT kota, unit Anda diminta menampilkan kesenian Betawi seperti ondel-ondel. Sebagian anggota merasa malu. Sikap yang paling tepat adalah ....", opts:[{t:"Meyakinkan tim bahwa menampilkan budaya Betawi adalah kebanggaan dan mengajak berlatih bersama dengan gembira", s:5},{t:"Ikut berpartisipasi dalam penampilan ondel-ondel tersebut", s:4},{t:"Mengikuti saja keputusan tim meski merasa malu", s:3},{t:"Menolak tampil dengan alasan tidak bisa menari", s:2},{t:"Mengejek budaya Betawi sebagai norak di depan tim", s:1}], ex:"Menumbuhkan kebanggaan pada budaya lokal mengubah rasa malu menjadi semangat; mengejek budaya sendiri adalah mentalitas rendah diri."},
{id:"TKP-2144", q:"Seorang warga marah-marah di loket pelayanan karena merasa dipersulit, dan tim Anda yang bertugas terlihat kewalahan. Sikap yang paling tepat adalah ....", opts:[{t:"Segera mendampingi rekan, menenangkan warga dengan empati, dan bersama mencari solusi atas permasalahannya", s:5},{t:"Membantu rekan menenangkan warga tersebut", s:4},{t:"Menonton dari jauh karena bukan giliran piket Anda", s:3},{t:"Menyalahkan rekan yang tidak becus menangani warga", s:2},{t:"Mengusir warga tersebut dengan kasar agar tidak mengganggu", s:1}], ex:"Sigap mendampingi rekan menghadapi warga yang emosi menunjukkan soliditas tim pelayanan; mengusir warga dengan kasar mencoreng citra instansi."},
{id:"TKP-2145", q:"Atasan meminta Anda menandatangani dokumen laporan yang belum sempat Anda baca karena terburu-buru. Sikap yang paling tepat adalah ....", opts:[{t:"Meminta waktu sebentar untuk membaca dan memahami isinya sebelum menandatangani, karena tanda tangan adalah pertanggungjawaban", s:5},{t:"Membaca cepat isi dokumen sebelum menandatanganinya", s:4},{t:"Menandatanganinya karena percaya pada atasan", s:3},{t:"Menandatanganinya agar tidak dianggap lamban", s:2},{t:"Menandatanganinya lalu menyalahkan atasan bila ada masalah", s:1}], ex:"Memastikan memahami isi sebelum menandatangani adalah prinsip akuntabilitas; tanda tangan tanpa membaca adalah keteledoran yang berisiko hukum."},
{id:"TKP-2146", q:"Rekan Anda yang bersuku Banjar mengundang tim ke acara haul keluarga yang rutin digelar setiap tahun. Sikap yang paling tepat adalah ....", opts:[{t:"Menghadiri dengan menghormati kekhusyukan acara haul sebagai tradisi keagamaan dan budaya yang mulia", s:5},{t:"Menghadiri undangan haul tersebut", s:4},{t:"Mengucapkan salam takziah tanpa hadir", s:3},{t:"Menolak hadir karena tidak mengenal yang dihaul", s:2},{t:"Menganggap haul sebagai bidah dan mengkritiknya", s:1}], ex:"Menghormati tradisi haul rekan menunjukkan penghargaan pada keyakinan dan budayanya; mengkritik keyakinannya adalah intoleransi beragama."},
{id:"TKP-2147", q:"Banjir membuat Hendra terlambat masuk kantor dan pekerjaannya menumpuk. Ia terlihat panik. Sikap yang paling tepat adalah ....", opts:[{t:"Menenangkannya, membantu memilah pekerjaan yang paling mendesak, dan ikut mengerjakannya bersama", s:5},{t:"Membantu Hendra menyelesaikan pekerjaannya yang menumpuk", s:4},{t:"Membiarkannya mengejar sendiri ketertinggalannya", s:3},{t:"Menyindirnya agar berangkat lebih pagi lain kali", s:2},{t:"Melaporkannya sebagai pegawai yang tidak disiplin", s:1}], ex:"Membantu rekan yang tertimpa musibah mengejar ketertinggalan adalah empati dan solidaritas; melaporkannya sebagai tidak disiplin mengabaikan keadaan kahar."},
{id:"TKP-2148", q:"Rekan Anda yang berasal dari Asmat memamerkan ukiran kayunya yang indah di kantor dan banyak yang mengagumi. Sikap yang paling tepat adalah ....", opts:[{t:"Mengapresiasi dengan tulus dan mengajak rekan lain mengenal makna filosofis di balik ukiran Asmat sebagai kekayaan budaya bangsa", s:5},{t:"Memuji keindahan ukiran tersebut dengan tulus", s:4},{t:"Melihat sekilas tanpa banyak komentar", s:3},{t:"Menganggapnya sekadar pajangan biasa", s:2},{t:"Meremehkannya sebagai kerajinan primitif", s:1}], ex:"Mengapresiasi sekaligus mengenalkan makna budaya di balik karya rekan menumbuhkan kebanggaan pada keberagaman; meremehkannya sebagai primitif adalah penghinaan budaya."},
{id:"TKP-2149", q:"Tim Anda merayakan keberhasilan program dengan makan bersama. Petugas kebersihan dan keamanan yang turut membantu selama ini tidak diundang. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan agar mereka juga diundang dan diberi penghargaan, karena keberhasilan tim adalah hasil kerja semua pihak", s:5},{t:"Mengajak mereka bergabung dalam perayaan tersebut", s:4},{t:"Diam saja karena daftar undangan sudah ditetapkan", s:3},{t:"Menganggap mereka tidak perlu diundang karena bukan anggota tim", s:2},{t:"Melarang mereka ikut dengan alasan bukan levelnya", s:1}], ex:"Menghargai semua pihak yang berkontribusi termasuk staf pendukung menunjukkan kerendahan hati; merayakan eksklusif menumbuhkan kesenjangan."},
{id:"TKP-2150", q:"Seorang rekan mengajak Anda bergabung dengan organisasi kemasyarakatan yang berafiliasi politik tertentu. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan halus karena ASN wajib menjaga netralitas dan tidak terafiliasi politik praktis", s:5},{t:"Menolak ajakan tersebut", s:4},{t:"Mempertimbangkan dulu keuntungan bergabung", s:3},{t:"Bergabung diam-diam agar tidak ketahuan", s:2},{t:"Bergabung dan mengajak rekan lain ikut serta", s:1}], ex:"Menolak afiliasi politik praktis adalah wujud netralitas ASN yang diamanatkan undang-undang; bergabung diam-diam tetap melanggar netralitas."},{id:"TKP-2151", q:"Menjelang pemilu, dua rekan Anda berbeda pilihan politik dan perdebatan mereka mulai mengganggu suasana kerja tim. Sikap yang paling tepat adalah ....", opts:[{t:"Mengingatkan keduanya bahwa ASN wajib netral dan mengajak kembali fokus pada pekerjaan serta menjaga hubungan baik", s:5},{t:"Meminta keduanya tidak membawa politik ke kantor", s:4},{t:"Diam saja karena pilihan politik adalah hak pribadi", s:3},{t:"Ikut membela salah satu pilihan politik", s:2},{t:"Menyebarkan pilihan politik keduanya ke media sosial", s:1}], ex:"Mengingatkan netralitas ASN dan meredam perdebatan politik menjaga profesionalitas; menyebarkan pilihan politik rekan melanggar privasi dan netralitas."},
{id:"TKP-2152", q:"Rekan Anda yang beragama Kristen merayakan Paskah dan membagikan telur Paskah kepada tim. Sikap yang paling tepat adalah ....", opts:[{t:"Menerima dengan gembira dan mengucapkan selamat Paskah sebagai penghargaan atas kebersamaan dalam keberagaman", s:5},{t:"Menerima pemberiannya dan mengucapkan terima kasih", s:4},{t:"Menolak dengan halus karena tidak merayakan Paskah", s:3},{t:"Menerima tetapi tidak memakannya", s:2},{t:"Menganggap perayaan Paskah tidak perlu dibawa ke kantor", s:1}], ex:"Menghargai perayaan hari besar rekan lintas agama mempererat persaudaraan; menolak mentah-mentah menunjukkan ketidakpekaan toleransi."},
{id:"TKP-2153", q:"Kotak pengaduan warga penuh dengan keluhan yang harus ditindaklanjuti tim Anda minggu ini. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak tim memetakan dan membagi penanganan keluhan sesuai bidang, dengan tenggat jelas dan monitoring bersama", s:5},{t:"Ikut mengambil bagian menangani keluhan sesuai pembagian", s:4},{t:"Menunggu ketua tim membagi tugas penanganan", s:3},{t:"Memilih keluhan yang paling mudah saja", s:2},{t:"Mengabaikan keluhan warga karena terlalu banyak", s:1}], ex:"Pemetaan dan pembagian penanganan keluhan yang sistematis menunjukkan tanggung jawab pelayanan; mengabaikan keluhan mengkhianati amanah publik."},
{id:"TKP-2154", q:"Rekan Anda penganut Khonghucu akan merayakan Imlek dan memohon izin untuk sembahyang di kelenteng. Sikap yang paling tepat adalah ....", opts:[{t:"Mendukung izinnya sebagai hak menjalankan ibadah dan membantu mengatur pengganti tugasnya", s:5},{t:"Menyetujui izinnya sebagai hak beribadah", s:4},{t:"Menyerahkan keputusan kepada atasan", s:3},{t:"Menolak karena pekerjaan sedang menumpuk", s:2},{t:"Mengejek ritual di kelenteng sebagai kuno", s:1}], ex:"Memfasilitasi ibadah penganut Khonghucu sama seperti agama lain adalah keadilan dan toleransi; merendahkan ritualnya adalah diskriminasi keyakinan."},
{id:"TKP-2155", q:"Seorang rekan meminta Anda mendahulukan urusan administrasinya karena ia kenal dekat dengan atasan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan halus dan menjelaskan bahwa pelayanan mengikuti antrean dan prosedur yang berlaku untuk semua", s:5},{t:"Menolak karena tidak ingin melanggar prosedur", s:4},{t:"Mendahulukannya karena tidak ingin bermasalah dengan atasan", s:3},{t:"Mendahulukannya dengan imbalan tertentu", s:2},{t:"Mendahulukannya lalu menyebarkan bahwa atasan pilih kasih", s:1}], ex:"Menegakkan antrean dan prosedur tanpa pandang kedekatan menjunjung keadilan; mendahulukan karena koneksi adalah nepotisme yang merusak kepercayaan."},
{id:"TKP-2156", q:"Kantor Anda akan direnovasi dan seorang rekan pengguna kursi roda mengusulkan akses ramah disabilitas. Sebagian menganggap biayanya mahal. Sikap yang paling tepat adalah ....", opts:[{t:"Mendukung usulan aksesibilitas karena hak penyandang disabilitas, serta mengusulkan desain yang efisien biaya", s:5},{t:"Mendukung usulan rekan tersebut", s:4},{t:"Netral dan mengikuti keputusan rapat", s:3},{t:"Menolak karena anggarannya terbatas", s:2},{t:"Mengejek usulan tersebut sebagai mengada-ada", s:1}], ex:"Memperjuangkan aksesibilitas bagi penyandang disabilitas menegakkan kesetaraan; mengejeknya menunjukkan ketidakpekaan kemanusiaan."},
{id:"TKP-2157", q:"Menjelang deadline besar, seorang rekan mengajak Anda cuti bersama ke pantai dengan alasan refreshing agar tidak stres. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan halus dan mengajaknya menyelesaikan deadline terlebih dahulu, refreshing bisa dijadwalkan setelahnya", s:5},{t:"Menolak ajakan cuti tersebut karena deadline mendesak", s:4},{t:"Ikut cuti karena merasa juga butuh refreshing", s:3},{t:"Ikut cuti lalu menyalahkan rekan bila atasan marah", s:2},{t:"Ikut cuti dan mengajak rekan lain meninggalkan deadline", s:1}], ex:"Menunda kesenangan demi menyelesaikan amanah menunjukkan kedisiplinan dan tanggung jawab; mengajak kabur dari deadline mengkhianati tim."},
{id:"TKP-2158", q:"Dinas Anda menjalankan program untuk nelayan yang waktunya bertepatan dengan tradisi sedekah laut masyarakat setempat. Sikap yang paling tepat adalah ....", opts:[{t:"Menyesuaikan jadwal program agar tidak berbenturan dan bila mungkin bersinergi dengan tradisi sedekah laut sebagai penghormatan", s:5},{t:"Menghormati tradisi tersebut dan menggeser jadwal program", s:4},{t:"Menjalankan program sesuai jadwal karena sudah ditetapkan", s:3},{t:"Meminta nelayan mengabaikan tradisi demi program", s:2},{t:"Melarang tradisi sedekah laut karena dianggap menghambat program", s:1}], ex:"Menyelaraskan program dengan tradisi masyarakat menunjukkan kearifan dalam pelayanan; melarang tradisi setempat menimbulkan penolakan warga."},
{id:"TKP-2159", q:"Tim Anda berencana belajar bersama menghadapi ujian dinas kenaikan pangkat. Seorang rekan yang sudah senior enggan ikut karena malu. Sikap yang paling tepat adalah ....", opts:[{t:"Meyakinkan senior bahwa belajar bersama tidak mengenal usia dan mengajaknya dengan suasana yang santai dan saling mendukung", s:5},{t:"Mengajak senior ikut belajar bersama", s:4},{t:"Membiarkannya karena itu pilihannya", s:3},{t:"Mengejeknya sebagai senior yang takut kalah dari junior", s:2},{t:"Melarangnya ikut karena dianggap akan menghambat", s:1}], ex:"Merangkul senior dalam belajar bersama menumbuhkan budaya belajar tim tanpa sekat usia; mengejeknya justru mempermalukan dan memecah tim."},
{id:"TKP-2160", q:"Seorang rekan melontarkan hinaan terhadap suku Anda saat bercanda di depan tim. Anda merasa tersinggung. Sikap yang paling tepat adalah ....", opts:[{t:"Menegurnya dengan tegas namun santun bahwa candaan berbasis suku tidak bisa diterima, siapa pun sasarannya", s:5},{t:"Memintanya tidak mengulangi candaan seperti itu", s:4},{t:"Diam menahan tersinggung agar tidak dianggap baper", s:3},{t:"Membalas menghina sukunya agar impas", s:2},{t:"Mengajak rekan sesuku memusuhinya", s:1}], ex:"Menegur hinaan suku dengan prinsip, bukan emosi pribadi, menegakkan martabat semua suku; membalas menghina hanya melipatgandakan kebencian."},
{id:"TKP-2161", q:"Winda meminta Anda menuliskan surat rekomendasi beasiswa untuknya. Anda mengenal kinerjanya dengan baik. Sikap yang paling tepat adalah ....", opts:[{t:"Menuliskan rekomendasi secara jujur dan objektif sesuai fakta, baik kelebihan maupun kekurangannya", s:5},{t:"Menuliskan rekomendasi sesuai penilaian Anda yang sebenarnya", s:4},{t:"Menuliskan yang baik-baik saja agar ia lolos", s:3},{t:"Menolak dengan alasan sibuk", s:2},{t:"Menuliskan rekomendasi buruk agar ia gagal dan Anda tidak tersaingi", s:1}], ex:"Rekomendasi yang jujur dan objektif menjaga kredibilitas penilai; menjatuhkan rekan demi persaingan adalah kedengkian."},
{id:"TKP-2162", q:"Masyarakat di wilayah Anda berpantang melakukan urusan resmi pada hari-hari tertentu menurut adatnya, sehingga pelayanan sepi pada hari itu. Sikap yang paling tepat adalah ....", opts:[{t:"Memahami pantangan tersebut dan mengoptimalkan pelayanan di hari lain, sambil tetap membuka layanan darurat", s:5},{t:"Menghormati pantangan adat dan menyesuaikan jadwal pelayanan", s:4},{t:"Tetap membuka pelayanan normal seperti biasa", s:3},{t:"Memaksa warga datang di hari pantangan demi target pelayanan", s:2},{t:"Mengejek pantangan tersebut sebagai kebodohan", s:1}], ex:"Menyesuaikan ritme pelayanan dengan adat setempat tanpa mengorbankan layanan darurat adalah kearifan; memaksa warga melanggar pantangan merusak kepercayaan."},
{id:"TKP-2163", q:"Tim Anda mendapat tugas piket posko mudik Lebaran di perbatasan kota. Tidak ada yang mengajukan diri. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan pembagian piket bergilir yang adil dengan insentif yang jelas, dan Anda bersedia mengambil giliran pertama", s:5},{t:"Bersedia mengisi jadwal piket posko mudik", s:4},{t:"Menunggu ditunjuk karena tidak ada yang mau sukarela", s:3},{t:"Berpura-pura mudik agar tidak kebagian piket", s:2},{t:"Menghasut tim kompak menolak tugas piket tersebut", s:1}], ex:"Memberi contoh dengan mengambil giliran pertama dalam pembagian yang adil menunjukkan kepemimpinan dan pengabdian; berpura-pura mudik adalah ketidakjujuran."},
{id:"TKP-2164", q:"Saat ujian diklat, rekan sebangku Anda menyodorkan jawaban dan meminta Anda mencontek. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas dan fokus pada jawaban sendiri, karena kelulusan harus diraih dengan kejujuran", s:5},{t:"Menolak dan mengerjakan soal sendiri", s:4},{t:"Mengabaikannya tanpa menanggapi", s:3},{t:"Mencontek sedikit saja karena soalnya sulit", s:2},{t:"Mencontek lalu melaporkan rekan tersebut agar Anda aman", s:1}], ex:"Menolak mencontek dengan tegas menegakkan integritas ASN; mencontek lalu melaporkan adalah kemunafikan yang licik."},
{id:"TKP-2165", q:"Rekan Anda penganut kepercayaan lokal Kejawen sering dipandang aneh oleh sebagian pegawai. Sikap yang paling tepat adalah ....", opts:[{t:"Menghormati keyakinannya sebagai hak yang dilindungi dan menegur siapa pun yang merendahkannya", s:5},{t:"Memperlakukan rekan tersebut seperti rekan lainnya", s:4},{t:"Tidak ikut campur urusan keyakinannya", s:3},{t:"Ikut memandangnya aneh agar diterima kelompok", s:2},{t:"Menyebarkan bahwa kepercayaannya sesat", s:1}], ex:"Menghormati penganut kepercayaan lokal dan membelanya dari perundungan menjunjung kebebasan berkeyakinan; menyebarkan tuduhan sesat adalah intoleransi."},
{id:"TKP-2166", q:"Unit Anda kedatangan atasan baru. Tim berencana mengadakan acara penyambutan. Sikap yang paling tepat adalah ....", opts:[{t:"Berpartisipasi aktif menyukseskan acara penyambutan sebagai bentuk penghormatan dan awal kerjasama yang baik", s:5},{t:"Ikut membantu persiapan acara penyambutan", s:4},{t:"Hadir sekadarnya karena belum mengenalnya", s:3},{t:"Tidak ikut dengan alasan sibuk", s:2},{t:"Menyebarkan gosip negatif tentang atasan baru sebelum ia datang", s:1}], ex:"Menyambut pimpinan baru dengan hangat membuka lembaran kerjasama yang positif; menyebar gosip sebelum mengenalnya adalah prasangka yang merusak."},
{id:"TKP-2167", q:"Seorang rekan mengajak Anda berinvestasi pada skema yang menjanjikan keuntungan besar dalam waktu singkat. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan mengingatkan rekan agar waspada terhadap investasi bodong yang merugikan banyak orang", s:5},{t:"Menolak ajakan investasi tersebut", s:4},{t:"Mempertimbangkan dulu sambil mencari informasi", s:3},{t:"Ikut dengan modal kecil untuk coba-coba", s:2},{t:"Ikut dan mengajak rekan lain agar mendapat bonus perekrutan", s:1}], ex:"Menolak sekaligus mengingatkan bahaya investasi bodong melindungi rekan dari kerugian; ikut merekrut berarti menjadi bagian penipuan."},
{id:"TKP-2168", q:"Di lingkungan kerja Anda ada penganut Sunda Wiwitan yang menjalankan ritualnya dengan tertib. Sebagian rekan menganggapnya menyimpang. Sikap yang paling tepat adalah ....", opts:[{t:"Menghormati ritualnya sebagai kepercayaan yang sah dan mengajak rekan lain bersikap toleran", s:5},{t:"Membiarkannya menjalankan ritualnya dengan tenang", s:4},{t:"Tidak berpendapat soal keyakinannya", s:3},{t:"Ikut menganggapnya menyimpang", s:2},{t:"Melaporkan kegiatannya sebagai aliran sesat", s:1}], ex:"Menghormati penganut kepercayaan asli nusantara dan mengajak toleransi menjunjung keberagaman; menuduhnya sesat tanpa dasar adalah intoleransi."},
{id:"TKP-2169", q:"Kantor Anda terlihat kumuh dan pimpinan mengajak seluruh pegawai gotong royong membersihkannya akhir pekan ini. Sikap yang paling tepat adalah ....", opts:[{t:"Ikut gotong royong dengan semangat dan mengajak rekan lain, karena kebersihan kantor adalah tanggung jawab bersama", s:5},{t:"Ikut gotong royong membersihkan kantor", s:4},{t:"Ikut tetapi hanya mengawasi sambil berdiri", s:3},{t:"Tidak ikut dengan alasan ada acara keluarga", s:2},{t:"Menolak dengan alasan membersihkan kantor bukan tugas pegawai", s:1}], ex:"Gotong royong membersihkan kantor menumbuhkan rasa memiliki dan kebersamaan; menolak dengan alasan bukan tugas menunjukkan mentalitas sempit."},
{id:"TKP-2170", q:"Beberapa rekan mengajak Anda berdemonstrasi menolak kebijakan pimpinan yang baru. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak ikut demonstrasi dan mengusulkan agar keberatan disampaikan melalui forum resmi atau perwakilan yang santun", s:5},{t:"Tidak ikut demonstrasi dan tetap bekerja", s:4},{t:"Ikut menandatangani petisi penolakan saja", s:3},{t:"Ikut berdemonstrasi agar aspirasi didengar", s:2},{t:"Ikut berdemonstrasi sambil memprovokasi agar ricuh", s:1}], ex:"Menyalurkan keberatan melalui jalur resmi yang santun lebih beretika bagi ASN; demonstrasi anarkis merusak citra aparatur dan pelayanan."},
{id:"TKP-2171", q:"Wilayah tugas Anda berbatasan dengan komunitas Baduy yang memegang teguh adatnya. Program penyuluhan Anda harus masuk ke sana. Sikap yang paling tepat adalah ....", opts:[{t:"Mempelajari adat Baduy terlebih dahulu dan berkoordinasi dengan tetua adat agar penyuluhan diterima dengan baik", s:5},{t:"Meminta izin dan pendampingan tetua adat sebelum masuk", s:4},{t:"Masuk seperti biasa karena program ini untuk kebaikan mereka", s:3},{t:"Memaksa masuk meski ditolak warga", s:2},{t:"Membatalkan program karena adatnya dianggap menghambat", s:1}], ex:"Berkoordinasi dengan tetua adat dan menghormati kearifan Baduy membuka pintu penerimaan program; memaksa masuk adalah arogansi yang merusak kepercayaan."},
{id:"TKP-2172", q:"Tim Anda membentuk kelompok belajar bahasa Inggris untuk meningkatkan kompetensi. Seorang rekan yang lemah bahasa Inggris malu ikut. Sikap yang paling tepat adalah ....", opts:[{t:"Meyakinkannya bahwa kelompok ini untuk semua level dan mengajaknya mulai dari dasar tanpa rasa malu", s:5},{t:"Mengajaknya ikut belajar bersama", s:4},{t:"Membiarkannya memutuskan sendiri", s:3},{t:"Mengejeknya karena tidak bisa bahasa Inggris", s:2},{t:"Melarangnya ikut karena akan menghambat yang lain", s:1}], ex:"Menciptakan ruang belajar yang aman bagi semua level menumbuhkan kompetensi tim; mengejek atau melarangnya adalah perundungan."},
{id:"TKP-2173", q:"Anda mengetahui seorang rekan melakukan pelanggaran disiplin dan ia memohon Anda merahasiakannya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak merahasiakan dan menyarankan ia mengakui serta memperbaiki kesalahannya, karena menutupi pelanggaran merugikan instansi", s:5},{t:"Menolak merahasiakan pelanggaran tersebut", s:4},{t:"Merahasiakannya karena kasihan padanya", s:3},{t:"Merahasiakannya dengan imbalan tertentu", s:2},{t:"Merahasiakannya lalu menggunakannya untuk mengendalikannya", s:1}], ex:"Menolak menutupi pelanggaran dengan tetap mendorong perbaikan menjunjung integritas; merahasiakan demi imbalan adalah pemerasan."},
{id:"TKP-2174", q:"Dinas pertanian Anda akan menghadiri upacara adat panen masyarakat sebagai tamu kehormatan. Sikap yang paling tepat adalah ....", opts:[{t:"Hadir dengan penuh hormat, mengikuti tata cara adat, dan menjadikannya momentum mendekatkan program pertanian pada petani", s:5},{t:"Menghadiri upacara adat panen tersebut", s:4},{t:"Mengirim perwakilan saja karena kesibukan", s:3},{t:"Tidak hadir karena dianggap tidak ada kaitannya dengan tugas", s:2},{t:"Menganggap upacara panen sebagai takhayul yang tidak perlu dihadiri", s:1}], ex:"Menghadiri upacara adat panen dengan hormat sekaligus mendekatkan program pada petani adalah kearifan; meremehkannya memutus kedekatan dengan masyarakat."},
{id:"TKP-2175", q:"Tim Anda akan menghadapi audit dan banyak dokumen harus disiapkan dalam waktu singkat. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak tim membagi penyiapan dokumen sesuai tanggung jawab masing-masing dengan daftar periksa bersama agar tidak ada yang terlewat", s:5},{t:"Ikut menyiapkan dokumen sesuai bagian Anda dengan rapi", s:4},{t:"Menyiapkan seadanya karena audit adalah urusan pimpinan", s:3},{t:"Menyembunyikan dokumen yang bermasalah agar tidak ditemukan auditor", s:2},{t:"Memalsukan dokumen yang kurang agar terlihat lengkap", s:1}], ex:"Penyiapan audit yang sistematis dan jujur menunjukkan akuntabilitas tim; memalsukan atau menyembunyikan dokumen adalah pelanggaran hukum."},
{id:"TKP-2176", q:"Seorang rekan mengajak Anda bolos apel pagi dengan alasan apel hanya formalitas. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas dan mengingatkannya bahwa apel adalah kewajiban disiplin ASN", s:5},{t:"Menolak ajakan bolos apel tersebut", s:4},{t:"Ikut bolos sekali-sekali karena memang membosankan", s:3},{t:"Ikut bolos dan mengajak rekan lain", s:2},{t:"Ikut bolos lalu melaporkan rekan tersebut agar Anda terlihat disiplin", s:1}], ex:"Menolak bolos apel sekaligus mengingatkan kewajibannya menegakkan disiplin; ikut bolos lalu melaporkan adalah kemunafikan."},
{id:"TKP-2177", q:"Rekan Anda yang bersuku Tengger akan mengikuti upacara Yadnya Kasada di Gunung Bromo dan meminta izin. Sikap yang paling tepat adalah ....", opts:[{t:"Mendukung izinnya sebagai pelaksanaan adat sakral dan membantu mengatur pengganti tugasnya", s:5},{t:"Menyetujui izinnya dan memaklumi", s:4},{t:"Menyerahkan keputusan kepada atasan", s:3},{t:"Keberatan karena waktunya bertepatan dengan agenda penting", s:2},{t:"Mengejek ritual melempar sesaji ke kawah sebagai mubazir", s:1}], ex:"Menghormati upacara adat sakral Tengger dengan membantu pengaturan pengganti adalah toleransi budaya; mengejek ritualnya adalah penghinaan."},
{id:"TKP-2178", q:"Tim Anda mengadakan donor darah bersama dan Anda diminta menjadi koordinator. Sebagian rekan takut jarum suntik. Sikap yang paling tepat adalah ....", opts:[{t:"Memberi pemahaman tentang manfaat donor darah, memastikan prosesnya aman, dan menghargai siapa pun yang belum siap tanpa paksaan", s:5},{t:"Mengajak rekan-rekan berpartisipasi donor darah", s:4},{t:"Membiarkan yang mau ikut saja tanpa ajakan", s:3},{t:"Memaksa semua anggota tim ikut donor darah", s:2},{t:"Mengejek yang takut jarum sebagai penakut", s:1}], ex:"Mengedukasi manfaat donor darah tanpa paksaan menumbuhkan kepedulian sosial; memaksa atau mengejek yang takut justru menimbulkan trauma."},
{id:"TKP-2179", q:"Seorang rekan menawarkan Anda parsel mewah agar urusan administrasinya dipercepat. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas dan menjelaskan bahwa pelayanan mengikuti prosedur tanpa gratifikasi dalam bentuk apa pun", s:5},{t:"Menolak parsel tersebut", s:4},{t:"Menerima parselnya tetapi tetap melayani sesuai prosedur", s:3},{t:"Menerima parselnya dan mempercepat urusannya", s:2},{t:"Menerima parselnya lalu meminta tambahan", s:1}], ex:"Menolak gratifikasi dengan tegas adalah benteng integritas ASN; menerima dalam bentuk apa pun membuka pintu korupsi."},
{id:"TKP-2180", q:"Rekan Anda yang bersuku Lampung akan menggelar begawi adat yang besar dan mengundang tim. Sikap yang paling tepat adalah ....", opts:[{t:"Menghadiri dengan menghormati seluruh prosesi begawi sebagai kekayaan adat Lampung yang patut dibanggakan", s:5},{t:"Menghadiri undangan begawi tersebut", s:4},{t:"Mengucapkan selamat tanpa hadir", s:3},{t:"Menolak hadir karena acaranya terlalu mewah", s:2},{t:"Mengomentari begawi sebagai ajang pamer kekayaan", s:1}], ex:"Menghadiri dan menghargai begawi adat Lampung menunjukkan penghargaan pada budaya rekan; mencibirnya sebagai pamer adalah ketidaksopanan."},
{id:"TKP-2181", q:"Tim Anda diminta merancang inovasi pelayanan agar antrean warga lebih cepat. Sikap yang paling tepat adalah ....", opts:[{t:"Mengajak tim menggali masukan warga dan merancang solusi bersama, lalu mengusulkan uji coba inovasinya", s:5},{t:"Ikut berkontribusi ide dalam perancangan inovasi", s:4},{t:"Menunggu inovasi dirancang oleh yang lebih senior", s:3},{t:"Menolak terlibat karena inovasi bukan tugas Anda", s:2},{t:"Mengklaim ide inovasi tim sebagai gagasan pribadi Anda", s:1}], ex:"Merancang inovasi berbasis masukan warga secara kolaboratif menghasilkan solusi yang tepat guna; mengklaim ide tim sebagai milik pribadi adalah ketidakjujuran."},
{id:"TKP-2182", q:"Seorang rekan mengajak Anda taruhan bola dengan nominal besar di sela jam kerja. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas dan mengingatkannya bahwa judi dalam bentuk apa pun melanggar hukum dan etika ASN", s:5},{t:"Menolak ajakan taruhan tersebut", s:4},{t:"Mengabaikan ajakannya", s:3},{t:"Ikut dengan nominal kecil sekadar seru-seruan", s:2},{t:"Ikut dan menjadi bandar taruhannya", s:1}], ex:"Menolak judi sekaligus mengingatkan pelanggarannya menegakkan integritas; ikut meski kecil tetap melanggar hukum."},
{id:"TKP-2183", q:"Rekan Anda yang berasal dari Kutai mengajak tim melihat erau adat yang digelar di daerahnya. Sikap yang paling tepat adalah ....", opts:[{t:"Ikut serta dan mengapresiasi erau sebagai pesta budaya Kutai yang megah dan penuh makna", s:5},{t:"Ikut melihat perhelatan erau adat tersebut", s:4},{t:"Menolak dengan halus karena kesibukan", s:3},{t:"Menganggap erau hanya pesta pora tanpa manfaat", s:2},{t:"Mengejek adat Kutai sebagai ketinggalan zaman", s:1}], ex:"Mengapresiasi pesta adat erau sebagai warisan budaya menumbuhkan kebanggaan keberagaman; mengejeknya adalah penghinaan suku."},
{id:"TKP-2184", q:"Dua kelompok warga bertikai soal batas lahan dan tim Anda diminta memediasi. Masing-masing mengklaim Anda memihak lawannya. Sikap yang paling tepat adalah ....", opts:[{t:"Tetap netral, mendengarkan kedua belah pihak secara adil, dan memfasilitasi musyawarah berdasarkan data dan aturan yang berlaku", s:5},{t:"Memediasi dengan adil tanpa memihak siapa pun", s:4},{t:"Menyerahkan sepenuhnya kepada aparat keamanan", s:3},{t:"Memihak kelompok yang lebih dulu datang melapor", s:2},{t:"Memanfaatkan konflik untuk meminta imbalan dari kedua pihak", s:1}], ex:"Mediasi yang netral berbasis data dan musyawarah menyelesaikan konflik secara adil; meminta imbalan dari konflik adalah pemerasan."},
{id:"TKP-2185", q:"Rekan Anda meminta Anda berbohong kepada atasan bahwa ia sedang sakit padahal ia pergi berlibur. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas dan menyarankan ia mengajukan cuti resmi bila ingin berlibur", s:5},{t:"Menolak berbohong untuknya", s:4},{t:"Berbohong sekali ini karena ia rekan baik", s:3},{t:"Berbohong dengan syarat ia mentraktir Anda", s:2},{t:"Berbohong lalu mengancam akan membongkarnya bila ia tidak menuruti Anda", s:1}], ex:"Menolak berbohong dengan memberi jalan keluar yang benar menjunjung kejujuran; berbohong demi rekan berarti ikut melanggar disiplin."},
{id:"TKP-2186", q:"Rekan Anda yang bersuku Dayak Ngaju akan melaksanakan ritual tiwah untuk leluhurnya dan meminta doa restu tim. Sikap yang paling tepat adalah ....", opts:[{t:"Memberi doa restu dengan tulus dan menghormati ritual tiwah sebagai kewajiban adat yang sakral baginya", s:5},{t:"Mendoakan kelancaran ritualnya", s:4},{t:"Mengucapkan semoga lancar tanpa banyak komentar", s:3},{t:"Mengabaikannya karena tidak memahami ritual tiwah", s:2},{t:"Menganggap tiwah sebagai kemusyrikan dan mengkritiknya", s:1}], ex:"Menghormati ritual adat sakral rekan tanpa menghakimi keyakinannya adalah toleransi yang dewasa; mengkritik keyakinannya adalah intoleransi beragama."},
{id:"TKP-2187", q:"Tim Anda merencanakan bakti sosial ke panti asuhan akhir pekan ini. Seorang rekan enggan ikut karena malu dianggap pencitraan. Sikap yang paling tepat adalah ....", opts:[{t:"Meyakinkannya bahwa ketulusan dinilai dari niat dan mengajaknya fokus pada kebahagiaan anak-anak panti", s:5},{t:"Mengajaknya ikut bakti sosial tersebut", s:4},{t:"Membiarkannya tidak ikut", s:3},{t:"Mengejeknya sebagai orang yang tidak peduli sesama", s:2},{t:"Melarangnya ikut karena dianggap tidak ikhlas", s:1}], ex:"Meyakinkan dengan fokus pada niat dan manfaat bagi anak panti menumbuhkan kepedulian; mengejeknya justru mematikan empati."},
{id:"TKP-2188", q:"Seorang rekan mengajak Anda menyebarkan ujaran kebencian terhadap kelompok agama tertentu di media sosial. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas dan mengingatkannya bahwa ujaran kebencian melanggar hukum serta merusak kerukunan bangsa", s:5},{t:"Menolak ajakan tersebut", s:4},{t:"Mengabaikan ajakannya", s:3},{t:"Ikut menyebarkan dengan akun anonim", s:2},{t:"Ikut menyebarkan secara terang-terangan", s:1}], ex:"Menolak ujaran kebencian sekaligus mengingatkan konsekuensi hukumnya melindungi kerukunan; ikut menyebarkan adalah kejahatan yang memecah belah bangsa."},
{id:"TKP-2189", q:"Rekan Anda yang berasal dari Gorontalo mengundang tim ke acara adat pernikahan keluarganya. Sikap yang paling tepat adalah ....", opts:[{t:"Menghadiri dengan menghormati adat Gorontalo sebagai bentuk persaudaraan lintas budaya", s:5},{t:"Menghadiri undangan pernikahan tersebut", s:4},{t:"Mengirim ucapan selamat tanpa hadir", s:3},{t:"Menolak hadir tanpa alasan jelas", s:2},{t:"Berkomentar miring tentang adat Gorontalo", s:1}], ex:"Menghadiri dan menghormati adat pernikahan lintas suku mempererat tali persaudaraan; berkomentar miring tentang adatnya adalah penghinaan budaya."},
{id:"TKP-2190", q:"Tim Anda dilibatkan menyusun anggaran kegiatan tahun depan secara partisipatif. Sikap yang paling tepat adalah ....", opts:[{t:"Berkontribusi aktif dengan usulan berbasis kebutuhan nyata dan mengawal transparansi penyusunannya bersama tim", s:5},{t:"Ikut menyampaikan usulan kebutuhan unit Anda", s:4},{t:"Mengikuti saja hasil penyusunan yang ada", s:3},{t:"Mengusulkan anggaran besar untuk kepentingan pribadi", s:2},{t:"Memanipulasi angka anggaran untuk keuntungan kelompok Anda", s:1}], ex:"Partisipasi aktif berbasis kebutuhan nyata dengan transparansi mewujudkan anggaran yang akuntabel; memanipulasi angka adalah korupsi."},
{id:"TKP-2191", q:"Rekan Anda meminta Anda menggantikannya piket tanpa sepengetahuan atasan karena ia ada keperluan. Sikap yang paling tepat adalah ....", opts:[{t:"Menyarankannya mengajukan izin resmi terlebih dahulu, dan Anda bersedia menggantikan setelah ada persetujuan atasan", s:5},{t:"Bersedia menggantikan setelah ia izin resmi ke atasan", s:4},{t:"Menggantikannya diam-diam karena hanya sekali ini", s:3},{t:"Menolak mentah-mentah tanpa memberi solusi", s:2},{t:"Menggantikannya dengan imbalan uang", s:1}], ex:"Penggantian tugas melalui prosedur resmi menjaga tertib administrasi; menggantikan diam-diam melanggar disiplin meski niatnya menolong."},
{id:"TKP-2192", q:"Rekan Anda yang berasal dari Minahasa merayakan pengucapan syukur panen dan mengundang tim mencicipi hidangannya. Sikap yang paling tepat adalah ....", opts:[{t:"Menghadiri dengan gembira dan menghargai tradisi syukur panen sebagai ungkapan syukur yang universal", s:5},{t:"Menghadiri undangannya dan mencicipi hidangan", s:4},{t:"Mengucapkan selamat tanpa hadir", s:3},{t:"Menolak karena hidangannya tidak biasa bagi Anda", s:2},{t:"Mengejek makanannya sebagai tidak higienis", s:1}], ex:"Menghargai tradisi syukur panen lintas budaya menunjukkan keterbukaan; mengejek hidangannya adalah penghinaan yang menyakitkan."},
{id:"TKP-2193", q:"Hari raya besar tiba dan jadwal piket kantor harus tetap terisi. Sikap yang paling tepat dalam menyusunnya adalah ....", opts:[{t:"Menyusun jadwal piket bergilir yang adil dengan musyawarah, memastikan semua yang merayakan mendapat giliran libur yang seimbang", s:5},{t:"Menyusun jadwal piket secara bergilir dan adil", s:4},{t:"Menunjuk yang paling junior untuk mengisi semua piket", s:3},{t:"Mengundi siapa yang piket tanpa musyawarah", s:2},{t:"Memaksa yang berbeda agama dengan mayoritas untuk selalu piket", s:1}], ex:"Penjadwalan piket hari raya yang adil hasil musyawarah menghormati hak beribadah semua; memaksa minoritas selalu piket adalah diskriminasi."},
{id:"TKP-2194", q:"Seorang rekan mengajak Anda memfitnah atasan di media sosial agar ia dicopot dari jabatannya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas dan mengingatkannya bahwa fitnah adalah perbuatan tercela dan melanggar hukum", s:5},{t:"Menolak ajakan memfitnah tersebut", s:4},{t:"Mengabaikan ajakannya", s:3},{t:"Ikut menyebarkan fitnah dengan akun palsu", s:2},{t:"Ikut memfitnah secara terang-terangan", s:1}], ex:"Menolak fitnah sekaligus mengingatkan pelanggarannya menegakkan kehormatan; ikut menyebarkan fitnah adalah kejahatan pencemaran nama baik."},
{id:"TKP-2195", q:"Rekan Anda yang bersuku Sasak mengundang tim ke acara nyongkolan, arak-arakan pengantin khas Lombok. Sikap yang paling tepat adalah ....", opts:[{t:"Ikut serta dengan antusias dan menghormati kemeriahan nyongkolan sebagai kekayaan budaya Lombok", s:5},{t:"Ikut menyaksikan arak-arakan nyongkolan tersebut", s:4},{t:"Menolak dengan halus karena tidak terbiasa", s:3},{t:"Menganggap nyongkolan mengganggu ketertiban", s:2},{t:"Mengejek pakaian adat pengantinnya", s:1}], ex:"Mengapresiasi kemeriahan adat nyongkolan menunjukkan penghargaan pada budaya Sasak; mengejek pakaian adatnya adalah penghinaan."},
{id:"TKP-2196", q:"Akhir tahun, tim Anda melakukan evaluasi diri. Seorang rekan mengusulkan setiap anggota menyampaikan kekurangan dan kelebihannya secara terbuka. Sikap yang paling tepat adalah ....", opts:[{t:"Mendukung dan berpartisipasi jujur menyampaikan evaluasi diri sebagai bahan perbaikan tim ke depan", s:5},{t:"Ikut menyampaikan evaluasi diri secara terbuka", s:4},{t:"Menyampaikan yang baik-baik saja tentang diri sendiri", s:3},{t:"Menolak karena takut kekurangannya diketahui", s:2},{t:"Memanfaatkan momen untuk menjatuhkan rekan lain", s:1}], ex:"Evaluasi diri yang jujur dan terbuka menumbuhkan budaya perbaikan berkelanjutan; memanfaatkannya untuk menjatuhkan rekan adalah pengkhianatan."},
{id:"TKP-2197", q:"Seorang rekan merokok di area kantor yang jelas dilarang merokok. Sikap yang paling tepat adalah ....", opts:[{t:"Menegurnya dengan santun dan mengingatkannya pada aturan serta hak rekan lain atas udara bersih", s:5},{t:"Memintanya merokok di area yang diperbolehkan", s:4},{t:"Membiarkannya karena takut dianggap sok mengatur", s:3},{t:"Ikut merokok bersamanya", s:2},{t:"Melaporkannya langsung ke atasan tanpa menegur dulu", s:1}], ex:"Menegur santun dengan mengingatkan aturan dan hak orang lain menyelesaikan pelanggaran secara beradab; langsung melaporkan tanpa teguran melompati etika pembinaan."},
{id:"TKP-2198", q:"Rekan Anda yang berasal dari Ambon akan merayakan panas pela, ritual persaudaraan antar desa, dan mengundang tim. Sikap yang paling tepat adalah ....", opts:[{t:"Menghadiri dengan menghormati makna persaudaraan dalam ritual pela sebagai kearifan lokal yang mempersatukan", s:5},{t:"Menghadiri undangan ritual pela tersebut", s:4},{t:"Mengucapkan selamat tanpa hadir", s:3},{t:"Menolak hadir karena tidak memahami maknanya", s:2},{t:"Menganggap ritual pela sebagai kemusyrikan", s:1}], ex:"Menghormati ritual persaudaraan pela sebagai kearifan pemersatu menunjukkan penghargaan budaya; menilainya dengan kacamata keyakinan sendiri adalah intoleransi."},
{id:"TKP-2199", q:"Unit Anda kedatangan CPNS baru yang akan bergabung dengan tim. Sikap yang paling tepat dalam menyambutnya adalah ....", opts:[{t:"Menyambut dengan hangat, mengenalkannya pada seluruh tim dan alur kerja, serta menunjuk pendamping agar ia cepat beradaptasi", s:5},{t:"Menyambutnya dan menawarkan bantuan bila membutuhkan", s:4},{t:"Menyambut sekadarnya seperti biasa", s:3},{t:"Mengabaikannya dan membiarkannya mencari tahu sendiri", s:2},{t:"Memanfaatkannya untuk melimpahkan pekerjaan yang tidak disukai", s:1}], ex:"Penyambutan hangat dengan pendampingan mempercepat integrasi anggota baru ke dalam tim; melimpahkan pekerjaan yang tidak disukai adalah perundungan."},
{id:"TKP-2200", q:"Rapat kerja akan dibuka dengan doa. Peserta rapat berasal dari berbagai agama. Sikap yang paling tepat adalah ....", opts:[{t:"Mengusulkan doa pembuka dipimpin bergantian perwakilan tiap agama atau doa bersama yang universal, disepakati melalui musyawarah", s:5},{t:"Mengusulkan doa dipimpin bergilir sesuai agama peserta", s:4},{t:"Mengikuti saja siapa pun yang memimpin doa", s:3},{t:"Bersikeras doa dipimpin sesuai agama mayoritas peserta", s:2},{t:"Menolak adanya doa pembuka dengan alasan mengganggu yang berbeda keyakinan", s:1}], ex:"Doa pembuka yang inklusif hasil musyawarah menghormati seluruh keyakinan peserta rapat; memaksakan agama mayoritas mengingkari semangat toleransi."}
];